package analyzer

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"unicode"

	"declscope/internal/checker"
	"declscope/internal/load"
)

const shrinkUsage = `Usage: declscope shrink [flags] [packages]

Reports the exported declarations of internal packages that nothing outside
their package uses, and with -fix unexports them.

Every package of the module is loaded, whatever the patterns name: an importer
outside them still counts. In a workspace, every module of it is loaded. The
patterns only choose which packages to report on, and default to ./... They
mean what they mean to the go command: a pattern it rejects stops the run, and
one that matches no package is warned about. Build tags come from GOFLAGS, as
for the analyzer.

A fix is offered only where no use can exist outside the package. Where a use
is possible but cannot be proved, such as a type that escapes into an
interface, the report stays and says why no fix is offered.

`

// isInternal reports whether an import path has an internal element.
func isInternal(path string) bool {
	for _, e := range strings.Split(path, "/") {
		if e == "internal" {
			return true
		}
	}
	return false
}

// shrinkCand is an exported declaration of a judged package.
type shrinkCand struct {
	obj    types.Object
	name   string
	kind   string
	ident  *ast.Ident
	key    string // baseline name: Type.member for members and methods
	ns     string
	file   *fileInfo
	doc    *ast.CommentGroup
	target *target
	typeOf *types.TypeName // the type of a field or method
	setOf  *types.TypeName // the type of a const set
	unit   *shrinkUnit
	member bool
	method bool
	isTest bool

	external bool // used outside the package
	xtest    bool // used by the external tests
	setKept  bool // another value of its const set keeps its name
	ignored  bool // an ignore of overexported, or the baseline, keeps its name
	reason   string
	fixable  bool
}

type shrinkUnit struct {
	path  string
	pkg   *load.Package
	model *model
	cands []*shrinkCand
	rules *Rules
	noFix string // why no declaration of the package can be fixed
	base  Baseline
}

// ShrinkMain runs "declscope shrink".
func ShrinkMain(args []string) int {
	fs := flag.NewFlagSet("declscope shrink", flag.ExitOnError)
	config := fs.String("config", "", "path to a declscope YAML config file, for the baseline it names")
	fix := fs.Bool("fix", false, "unexport every declaration a fix is offered for")
	fs.Usage = func() {
		fmt.Fprint(fs.Output(), shrinkUsage)
		fs.PrintDefaults()
	}
	fs.Parse(args)
	patterns := fs.Args()
	if len(patterns) == 0 {
		patterns = []string{"./..."}
	}
	res, err := runShrink(patterns, *config, "shrink", true)
	if err != nil {
		fmt.Fprintf(os.Stderr, "declscope shrink: %v\n", err)
		return 1
	}
	var lines []*shrinkFinding
	for _, f := range res.findings {
		lines = append(lines, f)
	}
	if *fix {
		var unfixed []*shrinkFinding
		var fixed []*shrinkFinding
		for _, f := range lines {
			if f.fix != nil {
				fixed = append(fixed, f)
			} else {
				unfixed = append(unfixed, f)
			}
		}
		if err := applyShrinkFixes(res.fset, fixed); err != nil {
			fmt.Fprintf(os.Stderr, "declscope shrink: %v\n", err)
			return 1
		}
		lines = unfixed
	}
	for _, f := range lines {
		fmt.Fprintf(os.Stdout, "%s: %s\n", res.fset.Position(f.pos), f.message)
	}
	if len(lines) > 0 {
		return 3
	}
	return 0
}

type shrinkFinding struct {
	pos     token.Pos
	message string
	fix     []checker.TextEdit
	cand    *shrinkCand
	unit    *shrinkUnit
	ns      string
	key     string
	ignored bool
}

type shrinkResult struct {
	fset     *token.FileSet
	findings []*shrinkFinding
	units    []*shrinkUnit
	all      []*shrinkFinding // every finding before ignores and baselines
	skipped  map[string]bool
}

// goModules lists the main modules of the go command run here.
func goModules() ([]load.Module, error) {
	cmd := exec.Command("go", "list", "-m", "-json")
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("%s", strings.TrimSpace(errb.String()))
	}
	var mods []load.Module
	for dec := json.NewDecoder(&out); dec.More(); {
		var m load.Module
		if err := dec.Decode(&m); err != nil {
			return nil, err
		}
		mods = append(mods, m)
	}
	return mods, nil
}

// matched lists the packages the patterns select, and the patterns that
// select none.
func matchedPackages(patterns []string) (map[string]bool, []string, error) {
	args := append([]string{"list", "-e", "-json=ImportPath,Match,Error,DepOnly,Dir", "--"}, patterns...)
	cmd := exec.Command("go", args...)
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		return nil, nil, fmt.Errorf("err: %v: stderr: %s", err, errb.String())
	}
	sel := make(map[string]bool)
	used := make(map[string]bool)
	var rejected []string
	for dec := json.NewDecoder(&out); dec.More(); {
		var p struct {
			ImportPath string
			Dir        string
			Match      []string
			DepOnly    bool
			Error      *struct{ Err string }
		}
		if err := dec.Decode(&p); err != nil {
			return nil, nil, err
		}
		if p.DepOnly {
			continue
		}
		if p.Error != nil {
			// The go command rejects the pattern, or cannot read the
			// package it names.
			rejected = append(rejected, strings.TrimRight(p.Error.Err, "\n"))
			continue
		}
		sel[p.ImportPath] = true
		for _, m := range p.Match {
			used[m] = true
		}
	}
	if len(rejected) > 0 {
		sort.Strings(rejected)
		return nil, nil, fmt.Errorf("%s", strings.Join(rejected, "\n"))
	}
	var none []string
	for _, p := range patterns {
		if !used[p] {
			none = append(none, p)
		}
	}
	return sel, none, nil
}

// runShrink judges the internal packages the patterns select. A failure
// that stops the run is returned; what it judges, warns about and leaves out
// is printed under the name of the command.
func runShrink(patterns []string, configPath, cmdName string, warn bool) (*shrinkResult, error) {
	selected, none, err := matchedPackages(patterns)
	if err != nil {
		return nil, err
	}
	if len(selected) == 0 {
		return nil, fmt.Errorf("%s matched no packages", strings.Join(patterns, " "))
	}
	if warn {
		for _, p := range none {
			fmt.Fprintf(os.Stderr, "declscope %s: warning: %q matched no packages\n", cmdName, p)
		}
	}
	mods, err := goModules()
	if err != nil {
		return nil, err
	}
	var all []string
	for _, m := range mods {
		all = append(all, m.Dir+string(filepath.Separator)+"...")
	}
	pkgs, err := load.Load(&load.Config{Tests: true}, all...)
	if err != nil {
		return nil, err
	}
	us := units(pkgs)
	// Every variant with errors of its own is named, by its own first error.
	seenFail := make(map[string]bool)
	var failed []string
	for _, p := range pkgs {
		if isTestMain(p) || len(p.Errors) == 0 {
			continue
		}
		line := p.PkgPath + ": " + failureOf(p)
		if !seenFail[line] {
			seenFail[line] = true
			failed = append(failed, line)
		}
	}
	if len(failed) > 0 {
		sort.Strings(failed)
		return nil, fmt.Errorf("these packages do not type-check, so no absence of a use means anything:\n  %s", strings.Join(failed, "\n  "))
	}
	loaded := make(map[string]bool)
	for _, u := range us {
		loaded[u.path] = true
	}

	res := &shrinkResult{skipped: make(map[string]bool)}
	if len(pkgs) > 0 {
		res.fset = pkgs[0].Fset
	}
	// Choose the packages to judge.
	var notJudged []string
	var paths []string
	for p := range selected {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	byPath := make(map[string]*unit)
	for _, u := range us {
		if !isXTest(u.pkg) {
			byPath[u.path] = u
		}
	}
	for _, path := range paths {
		if !isInternal(path) {
			continue
		}
		u := byPath[path]
		if u == nil {
			notJudged = append(notJudged, path+": ./... leaves it out, so this run does not load it")
			res.skipped[path] = true
			continue
		}
		if reason := skipReason(u.pkg); reason != "" {
			notJudged = append(notJudged, path+": "+reason)
			res.skipped[path] = true
			continue
		}
		rules, err := RulesFor(u.pkg, configPath)
		if err != nil {
			return nil, err
		}
		pass := &checker.Pass{Pkg: u.pkg, Fset: u.pkg.Fset, Files: u.pkg.Syntax, Types: u.pkg.Types, TypesInfo: u.pkg.TypesInfo}
		res.units = append(res.units, &shrinkUnit{path: path, pkg: u.pkg, model: newModel(pass, rules), rules: rules})
	}
	extra, more, err := moduleRanges(mods, res)
	if err != nil {
		return nil, err
	}
	notJudged = append(notJudged, more...)
	sort.Strings(notJudged)
	for _, s := range notJudged {
		fmt.Fprintf(os.Stderr, "declscope %s: not judged: %s\n", cmdName, s)
	}
	if res.fset == nil {
		return res, nil
	}
	// The baseline command regenerates the baseline, and never reads it.
	analyzeShrink(res, append(us, extra...), configPath, warn)
	return res, nil
}

// skipReason says why a package cannot be judged.
func skipReason(p *load.Package) string {
	if p.Name == "main" {
		return "package main"
	}
	if len(p.CgoFiles()) > 0 {
		return "the package uses cgo"
	}
	entries, err := os.ReadDir(p.Dir)
	if err == nil {
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			switch filepath.Ext(e.Name()) {
			case ".s", ".S", ".sx", ".c", ".cc", ".cpp", ".cxx", ".h", ".hh", ".hpp", ".hxx", ".m", ".f", ".F", ".for", ".f90", ".swig", ".swigcxx", ".syso":
				return "the package holds non-Go files"
			}
		}
	}
	return ""
}

// applyShrinkFixes writes the renames of the fixable findings.
func applyShrinkFixes(fset *token.FileSet, fs []*shrinkFinding) error {
	type edit struct {
		start, end int
		text       string
	}
	byFile := make(map[string][]edit)
	for _, f := range fs {
		for _, e := range f.fix {
			tf := fset.File(e.Pos)
			byFile[tf.Name()] = append(byFile[tf.Name()], edit{tf.Offset(e.Pos), tf.Offset(e.End), string(e.NewText)})
		}
	}
	var files []string
	for name := range byFile {
		files = append(files, name)
	}
	sort.Strings(files)
	for _, name := range files {
		src, err := os.ReadFile(name)
		if err != nil {
			return err
		}
		edits := byFile[name]
		sort.SliceStable(edits, func(i, j int) bool { return edits[i].start < edits[j].start })
		var out bytes.Buffer
		last := 0
		for _, e := range edits {
			if e.start < last {
				continue
			}
			out.Write(src[last:e.start])
			out.WriteString(e.text)
			last = e.end
		}
		out.Write(src[last:])
		if err := os.WriteFile(name, out.Bytes(), 0644); err != nil {
			return err
		}
	}
	return nil
}

var (
	_ = ast.IsExported
	_ = parser.ParseFile
	_ = unicode.IsUpper
	_ = types.Universe
)
package analyzer

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/parser"
	"go/token"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"declscope/internal/load"
)

// internalParent returns the path of the tree that may import an internal
// package: the parent of its last internal element.
func internalParent(path string) string {
	elems := strings.Split(path, "/")
	for i := len(elems) - 1; i >= 0; i-- {
		if elems[i] == "internal" {
			return strings.Join(elems[:i], "/")
		}
	}
	return path
}

func inTree(path, parent string) bool {
	return parent == "" || path == parent || strings.HasPrefix(path, parent+"/")
}

// buildModule is one module of a build list.
type buildModule struct {
	Path  string
	Main  bool
	Dir   string
	Error *struct{ Err string }
}

// readBuildList reads the build list of the module or workspace the go
// command finds from dir. A failure is described as it follows "reading the
// build list failed: ".
func readBuildList(dir string) ([]buildModule, string) {
	cmd := exec.Command("go", "list", "-m", "-e", "-json", "all")
	cmd.Dir = dir
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		if strings.Contains(errb.String(), "can't compute 'all' using the vendor directory") {
			return vendoredBuildList(dir)
		}
		return nil, strings.TrimSpace(errb.String())
	}
	var mods []buildModule
	for dec := json.NewDecoder(&out); dec.More(); {
		var m buildModule
		if err := dec.Decode(&m); err != nil {
			return mods, err.Error()
		}
		mods = append(mods, m)
	}
	for _, m := range mods {
		if m.Error != nil {
			return mods, m.Path + ": " + strings.TrimSpace(m.Error.Err)
		}
	}
	return mods, ""
}

// vendoredBuildList reads the build list of a module built in vendor mode
// from vendor/modules.txt: each module is read from its vendored copy.
func vendoredBuildList(dir string) ([]buildModule, string) {
	cmd := exec.Command("go", "list", "-m", "-json")
	cmd.Dir = dir
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		return nil, strings.TrimSpace(errb.String())
	}
	var mods []buildModule
	root := dir
	for dec := json.NewDecoder(&out); dec.More(); {
		var m buildModule
		if err := dec.Decode(&m); err != nil {
			return nil, err.Error()
		}
		mods = append(mods, m)
		if m.Dir != "" {
			root = m.Dir
		}
	}
	data, err := os.ReadFile(filepath.Join(root, "vendor", "modules.txt"))
	if err != nil {
		return nil, err.Error()
	}
	var vendored []buildModule
	for _, line := range strings.Split(string(data), "\n") {
		rest, ok := strings.CutPrefix(line, "# ")
		if !ok {
			continue
		}
		f := strings.Fields(rest)
		if len(f) == 0 {
			continue
		}
		vendored = append(vendored, buildModule{Path: f[0], Dir: filepath.Join(root, "vendor", filepath.FromSlash(f[0]))})
	}
	sort.SliceStable(vendored, func(i, j int) bool { return vendored[i].Path < vendored[j].Path })
	return append(mods, vendored...), ""
}

// modulePath returns the module path a go.mod file declares, tolerating
// unrelated problems in it, or "" if it declares none.
func modulePath(data []byte) string {
	for len(data) > 0 {
		line := data
		data = nil
		if i := bytes.IndexByte(line, '\n'); i >= 0 {
			line, data = line[:i], line[i+1:]
		}
		if i := bytes.Index(line, []byte("//")); i >= 0 {
			line = line[:i]
		}
		line = bytes.TrimSpace(line)
		rest, ok := bytes.CutPrefix(line, []byte("module"))
		if !ok {
			continue
		}
		n := len(rest)
		rest = bytes.TrimSpace(rest)
		if len(rest) == n || len(rest) == 0 {
			continue
		}
		if rest[0] == '"' || rest[0] == '`' {
			p, err := strconv.Unquote(string(rest))
			if err != nil {
				return ""
			}
			return p
		}
		return string(rest)
	}
	return ""
}

type nestedModule struct {
	path, dir string
}

// findNested lists the modules below a module root.
func findNested(root string) ([]nestedModule, error) {
	var out []nestedModule
	var failed error
	filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil || !d.IsDir() || path == root {
			return nil
		}
		if d.Name() == ".git" {
			return filepath.SkipDir
		}
		gomod := filepath.Join(path, "go.mod")
		data, err := os.ReadFile(gomod)
		if err != nil {
			return nil
		}
		mp := modulePath(data)
		if mp == "" {
			failed = fmt.Errorf("reading %s: no module path", gomod)
			return filepath.SkipAll
		}
		out = append(out, nestedModule{path: mp, dir: path})
		return nil
	})
	return out, failed
}

// moduleImports lists, sorted, the import paths the Go files of a module
// copy name, whatever their build constraints.
func moduleImports(root string) []string {
	seen := make(map[string]bool)
	var out []string
	filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() {
			if path == root {
				return nil
			}
			if d.Name() == "vendor" {
				return filepath.SkipDir
			}
			if _, err := os.Stat(filepath.Join(path, "go.mod")); err == nil {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(d.Name(), ".go") {
			return nil
		}
		f, _ := parser.ParseFile(token.NewFileSet(), path, nil, parser.ImportsOnly)
		if f == nil {
			return nil
		}
		for _, is := range f.Imports {
			if p, err := strconv.Unquote(is.Path.Value); err == nil && !seen[p] {
				seen[p] = true
				out = append(out, p)
			}
		}
		return nil
	})
	sort.Strings(out)
	return out
}

// moduleRanges judges what the modules around the main ones mean for the
// judged packages. Nested modules that may import a package and read it from
// other source, or fail to load, take it out of judgement; so does a module
// of the build list that may hold an importer. A module that a nested module
// builds from outside the tree and that imports an internal package withholds
// the fixes of its range. It returns the packages of the nested modules,
// whose uses count, and the packages it takes out of judgement, with the
// reason.
func moduleRanges(mods []load.Module, res *shrinkResult) ([]*unit, []string, error) {
	loaded := make(map[string]bool)
	for _, m := range mods {
		loaded[filepath.Clean(m.Dir)] = true
	}
	var nested []nestedModule
	for _, root := range mods {
		ns, err := findNested(root.Dir)
		if err != nil {
			return nil, nil, err
		}
		nested = append(nested, ns...)
	}
	for _, nm := range nested {
		loaded[filepath.Clean(nm.dir)] = true
	}

	var extra []*unit
	var notJudged []string
	drop := func(su *shrinkUnit, reason string) {
		notJudged = append(notJudged, su.path+": "+reason)
		res.skipped[su.path] = true
	}
	judged := func() []*shrinkUnit {
		var out []*shrinkUnit
		for _, su := range res.units {
			if !res.skipped[su.path] {
				out = append(out, su)
			}
		}
		return out
	}

	imports := make(map[string][]string)
	for _, nm := range nested {
		var inRange []*shrinkUnit
		for _, su := range judged() {
			if inTree(nm.path, internalParent(su.path)) {
				inRange = append(inRange, su)
			}
		}
		if len(inRange) > 0 {
			pkgs, err := load.Load(&load.Config{Dir: nm.dir, Tests: true}, "./...")
			for _, su := range inRange {
				if reason := nestedFailure(pkgs, err, su); reason != "" {
					drop(su, fmt.Sprintf("the nested module %s may import it, and %s", nm.path, reason))
				}
			}
			if err == nil {
				extra = append(extra, units(pkgs)...)
			}
		}

		list, failure := readBuildList(nm.dir)
		for _, su := range judged() {
			if su.noFix != "" {
				continue
			}
			parent := internalParent(su.path)
			if failure != "" && inTree(nm.path, parent) {
				su.noFix = fmt.Sprintf("the build list of the nested module %s cannot be read, and a module it names may use it: reading the build list failed: %s", nm.path, failure)
				continue
			}
			for _, m := range list {
				if m.Main || m.Dir == "" || loaded[filepath.Clean(m.Dir)] {
					continue
				}
				imps, ok := imports[m.Dir]
				if !ok {
					imps = moduleImports(m.Dir)
					imports[m.Dir] = imps
				}
				if q := internalImport(imps, parent); q != "" {
					su.noFix = fmt.Sprintf("the build of the nested module %s uses %s from %s, which imports %s", nm.path, m.Path, m.Dir, q)
					break
				}
			}
		}
	}

	if units := judged(); len(units) > 0 {
		list, failure := readBuildList(".")
		for _, su := range units {
			if failure != "" {
				drop(su, "reading the build list failed: "+failure)
				continue
			}
			parent := internalParent(su.path)
			for _, m := range list {
				if m.Main || loaded[filepath.Clean(m.Dir)] {
					continue
				}
				if holds(m, parent) {
					drop(su, fmt.Sprintf("the build uses %s from %s", m.Path, m.Dir))
					break
				}
			}
		}
	}
	res.units = judged()
	return extra, notJudged, nil
}

// nestedFailure says why the load of a nested module leaves a package
// unjudged, or returns "".
func nestedFailure(pkgs []*load.Package, err error, su *shrinkUnit) string {
	if err != nil {
		return "loading it failed: " + err.Error()
	}
	var listed []string
	reads := false
	var from string
	load.Visit(pkgs, nil, func(p *load.Package) {
		for _, e := range p.Errors {
			// A compile error the go command met building export data is
			// a type error, not a failure to load.
			if e.Kind == load.ListError && !strings.HasPrefix(e.Msg, "# ") {
				listed = append(listed, p.PkgPath+": "+describeError(e))
				break
			}
		}
		if p.PkgPath == su.path && !reads {
			reads = true
			if p.Dir != su.pkg.Dir {
				from = p.Dir
				if p.Module != nil && p.Module.Dir != "" {
					from = p.Module.Dir
				}
			}
		}
	})
	if len(listed) > 0 {
		sort.Strings(listed)
		return "loading it failed: " + listed[0]
	}
	if !reads {
		return ""
	}
	var broken []string
	for _, p := range pkgs {
		if isTestMain(p) || len(p.Errors) == 0 {
			continue
		}
		broken = append(broken, fmt.Sprintf("its package %s does not type-check: %s", p.PkgPath, describeError(firstError(p))))
	}
	if len(broken) > 0 {
		sort.Strings(broken)
		return broken[0]
	}
	if from != "" {
		return fmt.Sprintf("it reads %s from %s", su.path, from)
	}
	return ""
}

// internalImport returns the first of the sorted import paths that names an
// internal package in the tree of parent, or "".
func internalImport(imps []string, parent string) string {
	for _, imp := range imps {
		if isInternal(imp) && inTree(imp, parent) {
			return imp
		}
	}
	return ""
}

// holds reports whether a module of the build list may hold a package in the
// tree of parent: its path lies in the tree, or above it with the tree's
// directory inside.
func holds(m buildModule, parent string) bool {
	if inTree(m.Path, parent) {
		return true
	}
	rel, ok := strings.CutPrefix(parent, m.Path+"/")
	if !ok || m.Dir == "" {
		return false
	}
	fi, err := os.Stat(filepath.Join(m.Dir, filepath.FromSlash(rel)))
	return err == nil && fi.IsDir()
}

package analyzer

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"

	"declscope/internal/load"
)

const surveyUsage = `Usage: declscope survey [flags] [packages]

Reports what was checked and what it found, one row per package, so that the
package to open first is the one at the top.

It decides nothing and gates nothing: the exit status is zero whatever the
counts say. Use declscope itself for that, and a baseline to adopt it.

`

type surveyConfig struct {
	Chain    []string        `json:"chain"`
	Packages int             `json:"packages"`
	Rules    surveyRulesJSON `json:"rules"`
}

type surveyRulesJSON struct {
	Boundary bool   `json:"boundary"`
	Qualify  string `json:"qualify"`
	Exported bool   `json:"exported"`
	Surplus  string `json:"surplus"`
	Unused   string `json:"unused"`
}

type surveyBaseline struct {
	Path    string `json:"path"`
	Entries int    `json:"entries"`
}

type surveyWorst struct {
	Namespace string `json:"namespace"`
	Failing   int    `json:"failing"`
	Targets   int    `json:"targets"`
}

type surveyLargest struct {
	From    string `json:"from"`
	To      string `json:"to"`
	Reached int    `json:"reached"`
	Uses    int    `json:"uses"`
}

type surveyPackage struct {
	Package    string `json:"package"`
	Namespaces int    `json:"namespaces"`
	CoreFiles  int    `json:"coreFiles"`
	AllCore    bool   `json:"allCore"`
	Boundary   struct {
		Asked     bool `json:"asked"`
		Reported  int  `json:"reported"`
		Baselined int  `json:"baselined"`
		Declared  int  `json:"declared"`
	} `json:"boundary"`
	Qualify struct {
		Asked     bool         `json:"asked"`
		Reported  int          `json:"reported"`
		Baselined int          `json:"baselined"`
		Exempt    int          `json:"exempt"`
		Worst     *surveyWorst `json:"worst,omitempty"`
	} `json:"qualify"`
	Largest *surveyLargest `json:"largest,omitempty"`

	nothingRead bool
}

// SurveyMain runs "declscope survey".
func SurveyMain(args []string) int {
	sc := newSubcommand("survey", surveyUsage, true, "path to a declscope YAML config file")
	sc.fs.Parse(args)
	patterns := sc.fs.Args()
	if len(patterns) == 0 {
		patterns = []string{"./..."}
	}
	if sc.format != "markdown" && sc.format != "json" {
		return sc.fail("unknown format %q: this flag takes markdown, json", sc.format)
	}
	pkgs, err := load.Load(&load.Config{Tests: sc.test}, patterns...)
	if err != nil {
		return sc.fail("%v", err)
	}
	us := units(pkgs)
	var failed []string
	var ok []*unit
	for _, u := range us {
		if u.illTyped() {
			failed = append(failed, u.path+": "+u.failure())
		} else {
			ok = append(ok, u)
		}
	}
	sort.Strings(failed)
	if len(failed) > 0 && !sc.allowErrors {
		fmt.Fprintf(os.Stderr, "declscope survey: these packages do not type-check, so their counts would be zero for a reason that is not the code:\n")
		for _, f := range failed {
			fmt.Fprintf(os.Stderr, "  %s\n", f)
		}
		fmt.Fprintf(os.Stderr, "pass -allow-errors to measure the rest anyway\n")
		return 1
	}
	if len(us) == 0 {
		return sc.fail("%s matched no packages", strings.Join(patterns, " "))
	}

	var configs []*surveyConfig
	configIndex := make(map[string]*surveyConfig)
	var baselines []*surveyBaseline
	baselineIndex := make(map[string]bool)
	totals := make(map[string]*RuleCount)
	for _, r := range ruleOrder {
		totals[r] = &RuleCount{Keyable: r == "boundary" || r == "qualify" || r == "surplus"}
	}
	var rows []*surveyPackage
	for _, u := range ok {
		rules, err := RulesFor(u.pkg, sc.config)
		if err != nil {
			return sc.fail("%v", err)
		}
		var base Baseline
		basePath := BaselinePath(u.pkg, rules)
		if basePath != "" {
			if base, err = LoadBaseline(basePath); err != nil {
				return sc.fail("%v", err)
			}
			if _, statErr := os.Stat(basePath); statErr == nil && !baselineIndex[basePath] {
				baselineIndex[basePath] = true
				baselines = append(baselines, &surveyBaseline{Path: basePath, Entries: base.Count()})
			}
		}
		key := strings.Join(rules.Chain, "\x00")
		c := configIndex[key]
		if c == nil {
			c = &surveyConfig{Chain: append([]string{}, rules.Chain...), Rules: surveyRulesJSON{
				Boundary: rules.Boundary, Qualify: rules.Qualify, Exported: rules.Exported, Surplus: rules.Surplus, Unused: rules.Unused,
			}}
			configIndex[key] = c
			configs = append(configs, c)
		}
		c.Packages++

		me := MeasurePackage(u.pkg, rules, base, basePath)
		for _, r := range ruleOrder {
			t, c := totals[r], me.Counts[r]
			if c.Asked {
				t.Asked = true
			}
			t.Found += c.Found
			t.Ignored += c.Ignored
			t.Baselined += c.Baselined
			t.Reported += c.Reported
		}
		rows = append(rows, surveyRow(me))
	}
	sort.SliceStable(rows, func(i, j int) bool {
		a := rows[i].outstanding()
		b := rows[j].outstanding()
		if a != b {
			return a > b
		}
		return rows[i].Package < rows[j].Package
	})
	if sc.format == "json" {
		type checks struct {
			TypeCheck struct {
				Packages int      `json:"packages"`
				Failed   []string `json:"failed"`
			} `json:"typeCheck"`
			Configs   []*surveyConfig   `json:"configs"`
			Baselines []*surveyBaseline `json:"baselines"`
		}
		var o struct {
			Checks   checks                `json:"checks"`
			Totals   map[string]*RuleCount `json:"totals"`
			Packages []*surveyPackage      `json:"packages"`
		}
		o.Checks.TypeCheck.Packages = len(us)
		o.Checks.TypeCheck.Failed = append([]string{}, failed...)
		o.Checks.Configs = append([]*surveyConfig{}, configs...)
		o.Checks.Baselines = append([]*surveyBaseline{}, baselines...)
		o.Totals = totals
		o.Packages = append([]*surveyPackage{}, rows...)
		data, _ := json.MarshalIndent(o, "", "  ")
		fmt.Fprintf(os.Stdout, "%s\n", data)
		return 0
	}
	writeSurveyMarkdown(os.Stdout, configs, baselines, len(us)-len(failed), failed, totals, rows)
	return 0
}

func surveyRow(me *Measure) *surveyPackage {
	p := &surveyPackage{
		Package:     me.Path,
		Namespaces:  len(me.Namespaces),
		CoreFiles:   me.CoreFiles,
		AllCore:     me.AllCore,
		nothingRead: me.NothingRead,
	}
	b := me.Counts["boundary"]
	p.Boundary.Asked = b.Asked
	p.Boundary.Reported = b.Reported
	p.Boundary.Baselined = b.Baselined
	declared := make(map[string]bool)
	for _, e := range me.Edges {
		if e.State == "declared" {
			declared[e.To+"\x00"+e.Declaration] = true
		}
	}
	p.Boundary.Declared = len(declared)
	q := me.Counts["qualify"]
	p.Qualify.Asked = q.Asked
	p.Qualify.Reported = q.Reported
	p.Qualify.Baselined = q.Baselined
	for _, n := range me.Namespaces {
		p.Qualify.Exempt += n.exempt
		if n.failing == 0 {
			continue
		}
		w := p.Qualify.Worst
		if w == nil || n.failing > w.Failing ||
			n.failing == w.Failing && n.failing*w.Targets > w.Failing*n.QualifyTargets {
			p.Qualify.Worst = &surveyWorst{Namespace: n.Namespace, Failing: n.failing, Targets: n.QualifyTargets}
		}
	}
	if len(me.Crossings) > 0 {
		c := me.Crossings[0]
		p.Largest = &surveyLargest{From: c.From, To: c.To, Reached: c.Reached, Uses: c.Uses}
	}
	return p
}

func writeSurveyMarkdown(w io.Writer, configs []*surveyConfig, baselines []*surveyBaseline, okCount int, failed []string, totals map[string]*RuleCount, rows []*surveyPackage) {
	fmt.Fprintf(w, "## Checks in force\n\n")
	var cells [][]string
	for _, c := range configs {
		r := &Rules{Boundary: c.Rules.Boundary, Qualify: c.Rules.Qualify, Exported: c.Rules.Exported, Surplus: c.Rules.Surplus, Unused: c.Rules.Unused}
		cells = append(cells, []string{"config", chainText(c.Chain), fmt.Sprint(c.Packages)})
		cells = append(cells, []string{"rules", rulesText(r), fmt.Sprint(c.Packages)})
	}
	for _, b := range baselines {
		cells = append(cells, []string{"baseline", fmt.Sprintf("`%s`, %s", b.Path, plural(b.Entries, "entry", "entries")), ""})
	}
	cells = append(cells, []string{"type check", fmt.Sprintf("%s ok, %d failed", plural(okCount, "package", "packages"), len(failed)), ""})
	writeTable(w, []column{{"check", false}, {"value", false}, {"packages", true}}, cells)
	fmt.Fprintln(w)
	if len(failed) > 0 {
		fmt.Fprintf(w, "Did not type-check, so given no row:\n\n")
		for _, f := range failed {
			fmt.Fprintf(w, "- `%s`\n", f)
		}
		fmt.Fprintln(w)
	}

	fmt.Fprintf(w, "## Findings\n\n")
	cells = nil
	for _, r := range ruleOrder {
		t := totals[r]
		cells = append(cells, []string{"`" + r + "`", num(t.Asked, t.Found), num(t.Asked, t.Ignored), num(t.Asked && t.Keyable, t.Baselined), num(t.Asked, t.Reported)})
	}
	writeTable(w, []column{{"rule", false}, {"found", true}, {"ignored", true}, {"baselined", true}, {"reported", true}}, cells)
	fmt.Fprintln(w)

	fmt.Fprintf(w, "## Packages — boundary\n\n")
	cells = nil
	for _, p := range rows {
		largest := "-"
		if p.Largest != nil {
			largest = fmt.Sprintf("%s → %s (%s)", p.Largest.From, p.Largest.To, plural(p.Largest.Reached, "declaration", "declarations"))
		}
		a := p.Boundary.Asked
		cells = append(cells, []string{packageCell(p), num(a, p.Boundary.Reported), num(a, p.Boundary.Baselined), num(a, p.Boundary.Declared), largest})
	}
	writeTable(w, []column{{"package", false}, {"reported", true}, {"baselined", true}, {"declared", true}, {"largest crossing", false}}, cells)
	fmt.Fprintln(w)

	fmt.Fprintf(w, "## Packages — qualify\n\n")
	cells = nil
	for _, p := range rows {
		worst := "-"
		if p.Qualify.Worst != nil {
			worst = fmt.Sprintf("%s %d of %d", p.Qualify.Worst.Namespace, p.Qualify.Worst.Failing, p.Qualify.Worst.Targets)
		}
		a := p.Qualify.Asked
		cells = append(cells, []string{"`" + p.Package + "`", num(a, p.Qualify.Reported), num(a, p.Qualify.Baselined), num(a, p.Qualify.Exempt), worst})
	}
	writeTable(w, []column{{"package", false}, {"reported", true}, {"baselined", true}, {"exempt", true}, {"worst namespace", false}}, cells)
	fmt.Fprintln(w)
}

// outstanding counts what is undecided in a package: its reported and
// baselined findings.
func (p *surveyPackage) outstanding() int {
	return p.Boundary.Reported + p.Boundary.Baselined + p.Qualify.Reported + p.Qualify.Baselined
}

func packageCell(p *surveyPackage) string {
	s := "`" + p.Package + "`"
	if p.nothingRead {
		s += " [nothing read]"
	}
	if p.AllCore {
		s += " [all core]"
	}
	return s
}
package analyzer

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"

	"declscope/internal/load"
)

const inspectUsage = `Usage: declscope inspect [flags] <package>

Reports the shape of one package: its namespaces, every crossing between them,
what became of each crossing, and where the naming rule stands.

Takes one package. A namespace is implicitly qualified by its package, so
counts from two packages cannot be added up, and averaging them away silently
would answer a question nobody asked.

`

// InspectMain runs "declscope inspect".
func InspectMain(args []string) int {
	sc := newSubcommand("inspect", inspectUsage, false, "path to a declscope YAML config file")
	sc.fs.Parse(args)
	patterns := sc.fs.Args()
	if len(patterns) == 0 {
		sc.fs.Usage()
		return 2
	}
	if sc.format != "markdown" && sc.format != "json" {
		return sc.fail("unknown format %q: this flag takes markdown, json", sc.format)
	}
	pkgs, err := load.Load(&load.Config{Tests: sc.test}, patterns...)
	if err != nil {
		return sc.fail("%v", err)
	}
	var us []*unit
	for _, u := range units(pkgs) {
		if !isXTest(u.pkg) {
			us = append(us, u)
		}
	}
	var failed []string
	for _, u := range us {
		if u.illTyped() {
			failed = append(failed, u.path+": "+u.failure())
		}
	}
	sort.Strings(failed)
	if len(failed) > 0 {
		fmt.Fprintf(os.Stderr, "declscope inspect: these packages do not type-check, so nothing can be measured:\n")
		for _, f := range failed {
			fmt.Fprintf(os.Stderr, "  %s\n", f)
		}
		return 1
	}
	if len(us) == 0 {
		return sc.fail("%s matched no packages", strings.Join(patterns, " "))
	}
	if len(us) > 1 {
		fmt.Fprintf(os.Stderr, "declscope inspect: this pattern matches %d packages, and a namespace of one means nothing in another:\n", len(us))
		for _, u := range us {
			fmt.Fprintf(os.Stderr, "  %s\n", u.path)
		}
		fmt.Fprintf(os.Stderr, "name one of them\n")
		return 1
	}
	u := us[0]
	rules, err := RulesFor(u.pkg, sc.config)
	if err != nil {
		return sc.fail("%v", err)
	}
	var base Baseline
	basePath := BaselinePath(u.pkg, rules)
	if basePath != "" {
		if base, err = LoadBaseline(basePath); err != nil {
			return sc.fail("%v", err)
		}
	}
	me := MeasurePackage(u.pkg, rules, base, basePath)
	if sc.format == "json" {
		writeInspectJSON(os.Stdout, me)
	} else {
		writeInspectMarkdown(os.Stdout, me)
	}
	return 0
}

func writeInspectJSON(w io.Writer, me *Measure) {
	type out struct {
		Package    string                `json:"package"`
		Config     []string              `json:"config"`
		AllCore    bool                  `json:"allCore"`
		Findings   map[string]*RuleCount `json:"findings"`
		Namespaces []*NamespaceInfo      `json:"namespaces"`
		Crossings  []*Crossing           `json:"crossings"`
		Edges      []*Edge               `json:"edges"`
		Names      []*NameInfo           `json:"names"`
	}
	o := out{
		Package:    me.Path,
		Config:     append([]string{}, me.Rules.Chain...),
		AllCore:    me.AllCore,
		Findings:   me.Counts,
		Namespaces: append([]*NamespaceInfo{}, me.Namespaces...),
		Crossings:  append([]*Crossing{}, me.Crossings...),
		Edges:      append([]*Edge{}, me.Edges...),
		Names:      append([]*NameInfo{}, me.Names...),
	}
	data, _ := json.MarshalIndent(o, "", "  ")
	fmt.Fprintf(w, "%s\n", data)
}

func writeInspectMarkdown(w io.Writer, me *Measure) {
	fmt.Fprintf(w, "# %s\n\n", me.Path)
	if len(me.Rules.Chain) > 0 {
		fmt.Fprintf(w, "Config: %s\n\n", chainText(me.Rules.Chain))
	}
	if me.NothingRead {
		fmt.Fprintf(w, "> No file of this package was read — every one is generated, or the filter removed them — so nothing here was checked.\n\n")
	}
	if me.AllCore {
		fmt.Fprintf(w, "> Every file is in the core namespace, so nothing crosses and no name is asked to carry one.\n\n")
	}

	fmt.Fprintf(w, "## Namespaces\n\n")
	var rows [][]string
	for _, n := range me.Namespaces {
		var files []string
		for _, f := range n.Files {
			files = append(files, "`"+f+"`")
		}
		rows = append(rows, []string{n.Namespace, strings.Join(files, ", "), fmt.Sprint(n.Declarations), num(me.QualifyAsked && !n.Core, n.QualifyTargets)})
	}
	writeTable(w, []column{{"namespace", false}, {"files", false}, {"declarations", true}, {"qualify targets", true}}, rows)
	fmt.Fprintln(w)

	fmt.Fprintf(w, "## Crossings\n\n")
	open := make(map[string]bool)
	for _, e := range me.Edges {
		if e.State == "open" {
			open[e.To+"\x00"+e.Declaration] = true
		}
	}
	if len(me.Crossings) == 0 && len(open) > 0 {
		fmt.Fprintf(w, "Open crossings only: %s shared by default rather than by decision, so there is nothing to put in the table or diagram.\n\n",
			plural(len(open), "declaration is", "declarations are"))
	} else if len(me.Crossings) == 0 {
		fmt.Fprintf(w, "Nothing crosses a namespace in this package.\n\n")
	} else {
		writeMermaid(w, me.Crossings)
		fmt.Fprintf(w, "<details>\n<summary>Table: %s</summary>\n\n", plural(len(me.Crossings), "crossing", "crossings"))
		b := me.BoundaryAsked
		rows = nil
		for _, c := range me.Crossings {
			mutual := ""
			if c.Mutual {
				mutual = "yes"
			}
			rows = append(rows, []string{
				c.From + " → " + c.To, mutual,
				num(b, c.Declared), num(b, c.Baselined), num(b, c.Reported), num(b, c.Clears),
				fmt.Sprintf("%d of %d", c.Reached, c.Declarations), fmt.Sprint(c.Uses),
			})
		}
		writeTable(w, []column{{"crossing", false}, {"mutual", false}, {"declared", true}, {"baselined", true}, {"reported", true}, {"clears", true}, {"reached", true}, {"uses", true}}, rows)
		fmt.Fprintf(w, "\n</details>\n\n")
	}
	if n := len(open); n > 0 && len(me.Crossings) > 0 {
		if n == 1 {
			fmt.Fprintf(w, "1 declaration is further: open, shared by default rather than by decision, so left out of the table and of the diagram.\n\n")
		} else {
			fmt.Fprintf(w, "%d declarations are further: open, shared by default rather than by decision, so left out of the table and of the diagram.\n\n", n)
		}
	}
	if len(me.Crossings) > 0 && me.BoundaryAsked {
		states := make(map[string]map[string]bool)
		for _, e := range me.Edges {
			if states[e.State] == nil {
				states[e.State] = make(map[string]bool)
			}
			states[e.State][e.To+"\x00"+e.Declaration] = true
		}
		fmt.Fprintf(w, "Declarations crossed: %d reported, %d baselined, %d declared. The columns above count within a pair, so they sum to more: a declaration reached from two namespaces is two rows and one finding.\n\n",
			len(states["reported"]), len(states["baselined"]), len(states["declared"]))
	}
	if len(me.Crossings) > 0 {
		writeMostReached(w, me)
	}

	fmt.Fprintf(w, "## Qualify\n\n")
	if !me.QualifyAsked {
		fmt.Fprintf(w, "Not asked: `rules.naming.qualify` does not apply to this package.\n\n")
		return
	}
	rows = nil
	for _, n := range me.Namespaces {
		if n.Core || n.QualifyTargets == 0 {
			rows = append(rows, []string{n.Namespace, "-", "-", "-", "-"})
			continue
		}
		rows = append(rows, []string{n.Namespace, fmt.Sprint(n.exempt), fmt.Sprint(n.baselined), fmt.Sprint(n.reported), fmt.Sprintf("%d of %d", n.failing, n.QualifyTargets)})
	}
	writeTable(w, []column{{"namespace", false}, {"exempt", true}, {"baselined", true}, {"reported", true}, {"saturation", true}}, rows)
	fmt.Fprintln(w)
}

// writeMermaid draws the crossings as a graph.
func writeMermaid(w io.Writer, cs []*Crossing) {
	fmt.Fprintf(w, "```mermaid\ngraph LR\n")
	ids := make(map[string]int)
	var nodes []string
	node := func(name string) {
		if _, ok := ids[name]; !ok {
			ids[name] = len(nodes)
			nodes = append(nodes, name)
		}
	}
	for _, c := range cs {
		node(c.From)
		node(c.To)
	}
	for i, n := range nodes {
		fmt.Fprintf(w, "  n%d[%q]\n", i, n)
	}
	for _, c := range cs {
		arrow := "-.->"
		switch {
		case c.Reported > 0:
			arrow = "==>"
		case c.Baselined > 0:
			arrow = "-->"
		}
		fmt.Fprintf(w, "  n%d %s|%d| n%d\n", ids[c.From], arrow, c.Reached, ids[c.To])
	}
	fmt.Fprintf(w, "```\n\n")
}

// writeMostReached ranks the declarations reached from other namespaces.
func writeMostReached(w io.Writer, me *Measure) {
	type row struct {
		decl, ns, state string
		from, uses      int
	}
	byDecl := make(map[string]*row)
	var rows []*row
	coreDecls := make(map[string]bool)
	for _, e := range me.Edges {
		if e.State == "open" {
			continue
		}
		key := e.To + "\x00" + e.Declaration
		if e.To == "(core)" {
			coreDecls[key] = true
			continue
		}
		r := byDecl[key]
		if r == nil {
			r = &row{decl: e.Declaration, ns: e.To, state: e.State}
			byDecl[key] = r
			rows = append(rows, r)
		}
		r.from++
		r.uses += e.Uses
	}
	sort.SliceStable(rows, func(i, j int) bool {
		a, b := rows[i], rows[j]
		if a.from != b.from {
			return a.from > b.from
		}
		if a.uses != b.uses {
			return a.uses > b.uses
		}
		if a.ns != b.ns {
			return a.ns < b.ns
		}
		return a.decl < b.decl
	})
	fmt.Fprintf(w, "## Most-reached declarations except `(core)`\n\n")
	if len(rows) > 10 {
		rows = rows[:10]
	}
	var cells [][]string
	for _, r := range rows {
		cells = append(cells, []string{"`" + r.decl + "`", r.ns, plural(r.from, "namespace", "namespaces"), r.state})
	}
	if len(cells) > 0 {
		writeTable(w, []column{{"declaration", false}, {"namespace", false}, {"reached from", false}, {"state", false}}, cells)
		fmt.Fprintln(w)
	}
	if n := len(coreDecls); n > 0 {
		if n == 1 {
			fmt.Fprintf(w, "1 declaration is further: the core's, which is the shared model and reached from everywhere by design.\n\n")
		} else {
			fmt.Fprintf(w, "%d declarations are further: the core's, which is the shared model and reached from everywhere by design.\n\n", n)
		}
	}
}
package analyzer

import (
	"sort"

	"declscope/internal/checker"
	"declscope/internal/load"
)

// RuleCount tallies one rule's findings in a package.
type RuleCount struct {
	Asked     bool `json:"asked"`
	Keyable   bool `json:"keyable"`
	Found     int  `json:"found"`
	Ignored   int  `json:"ignored"`
	Baselined int  `json:"baselined"`
	Reported  int  `json:"reported"`
}

// Edge is one declaration reached from one other namespace.
type Edge struct {
	From        string `json:"from"`
	To          string `json:"to"`
	Declaration string `json:"declaration"`
	Kind        string `json:"kind"`
	Uses        int    `json:"uses"`
	State       string `json:"state"`

	decl *decl
}

// Crossing folds the edges between two namespaces, open ones left out.
type Crossing struct {
	From         string `json:"from"`
	To           string `json:"to"`
	Mutual       bool   `json:"mutual"`
	Declared     int    `json:"declared"`
	Baselined    int    `json:"baselined"`
	Reported     int    `json:"reported"`
	Ignored      int    `json:"ignored"`
	Unchecked    int    `json:"unchecked"`
	Reached      int    `json:"reached"`
	Declarations int    `json:"declarations"`
	Uses         int    `json:"uses"`
	Clears       int    `json:"clears"`
}

// NamespaceInfo describes one namespace.
type NamespaceInfo struct {
	Namespace      string   `json:"namespace"`
	Files          []string `json:"files"`
	Core           bool     `json:"core"`
	Declarations   int      `json:"declarations"`
	QualifyTargets int      `json:"qualifyTargets"`

	failing, exempt, baselined, reported int
}

// NameInfo is one finding of the naming rule.
type NameInfo struct {
	Namespace   string `json:"namespace"`
	File        string `json:"file"`
	Declaration string `json:"declaration"`
	Kind        string `json:"kind"`
	Exported    bool   `json:"exported"`
	State       string `json:"state"`
	Fixable     bool   `json:"fixable"`
}

// Measure is everything survey and inspect report about one package.
type Measure struct {
	Path          string
	Pkg           *load.Package
	Rules         *Rules
	Baseline      string // path of the baseline consulted, if any
	Counts        map[string]*RuleCount
	Namespaces    []*NamespaceInfo
	Edges         []*Edge
	Crossings     []*Crossing
	Names         []*NameInfo
	NothingRead   bool
	CoreFiles     int
	AllCore       bool
	QualifyAsked  bool
	BoundaryAsked bool

	res *Result
}

var ruleOrder = []string{"boundary", "qualify", "surplus", "unused", "directive", "filter"}

// MeasurePackage analyzes a package and folds the results.
func MeasurePackage(pkg *load.Package, rules *Rules, base Baseline, basePath string) *Measure {
	pass := &checker.Pass{
		Pkg:       pkg,
		Fset:      pkg.Fset,
		Files:     pkg.Syntax,
		Types:     pkg.Types,
		TypesInfo: pkg.TypesInfo,
	}
	res := Analyze(pass, rules, base)
	m := res.Model
	me := &Measure{
		Path:     pkg.PkgPath,
		Pkg:      pkg,
		Rules:    rules,
		Baseline: basePath,
		Counts:   make(map[string]*RuleCount),
		res:      res,
	}
	me.NothingRead = len(m.files) == 0
	me.BoundaryAsked = rules.Boundary
	me.QualifyAsked = m.qualifyAsked()
	asked := map[string]bool{
		"boundary":  rules.Boundary,
		"qualify":   me.QualifyAsked,
		"surplus":   rules.Surplus != "off" && !me.NothingRead && !m.surplusStandsDown() && !(m.unseenTests && !m.testVariant),
		"unused":    rules.Unused != "off",
		"directive": true,
		"filter":    true,
	}
	for _, r := range ruleOrder {
		me.Counts[r] = &RuleCount{Asked: asked[r], Keyable: r == "boundary" || r == "qualify" || r == "surplus"}
	}
	for _, f := range res.Findings {
		c := me.Counts[f.rule]
		if c == nil {
			continue
		}
		c.Found++
		switch {
		case res.Ignored[f]:
			c.Ignored++
		case res.Baselined[f]:
			c.Baselined++
		default:
			c.Reported++
		}
	}

	// Namespaces.
	byNS := make(map[*namespace]*NamespaceInfo)
	for _, f := range m.files {
		info := byNS[f.ns]
		if info == nil {
			info = &NamespaceInfo{Namespace: f.ns.key(), Core: f.ns.core}
			byNS[f.ns] = info
			me.Namespaces = append(me.Namespaces, info)
		}
		info.Files = append(info.Files, f.base)
		if f.ns.core {
			me.CoreFiles++
		}
	}
	me.AllCore = len(m.files) > 0 && me.CoreFiles == len(m.files)
	sort.Slice(me.Namespaces, func(i, j int) bool { return me.Namespaces[i].Namespace < me.Namespaces[j].Namespace })

	boundaryOf := make(map[*decl]*finding)
	qualifyOf := make(map[*decl]*finding)
	for _, f := range res.Findings {
		if f.decl == nil {
			continue
		}
		switch f.rule {
		case "boundary":
			boundaryOf[f.decl] = f
		case "qualify":
			qualifyOf[f.decl] = f
		}
	}
	state := func(f *finding) string {
		switch {
		case res.Ignored[f]:
			return "ignored"
		case res.Baselined[f]:
			return "baselined"
		}
		return "reported"
	}
	for _, d := range m.decls {
		info := byNS[d.ns]
		info.Declarations++
		if me.QualifyAsked && m.qualifyTarget(d) {
			info.QualifyTargets++
			if f := qualifyOf[d]; f != nil {
				st := state(f)
				switch st {
				case "baselined":
					info.baselined++
					info.failing++
				case "reported":
					info.reported++
					info.failing++
				case "ignored":
					info.exempt++
					st = "exempt"
				}
				me.Names = append(me.Names, &NameInfo{
					Namespace:   d.ns.key(),
					File:        d.file.base,
					Declaration: d.display,
					Kind:        d.kind,
					Exported:    d.exported,
					State:       st,
					Fixable:     f.fix != nil,
				})
			}
		}
	}
	sort.SliceStable(me.Names, func(i, j int) bool {
		a, b := me.Names[i], me.Names[j]
		if a.Namespace != b.Namespace {
			return a.Namespace < b.Namespace
		}
		return a.Declaration < b.Declaration
	})

	// Edges: one per declaration and reaching namespace.
	for _, d := range m.decls {
		uses := make(map[*namespace]int)
		var order []*namespace
		for _, u := range d.crossing() {
			if uses[u.file.ns] == 0 {
				order = append(order, u.file.ns)
			}
			uses[u.file.ns]++
		}
		if len(order) == 0 {
			continue
		}
		st := m.edgeState(d, boundaryOf[d], state)
		for _, ns := range order {
			me.Edges = append(me.Edges, &Edge{
				From:        ns.key(),
				To:          d.ns.key(),
				Declaration: d.display,
				Kind:        d.kind,
				Uses:        uses[ns],
				State:       st,
				decl:        d,
			})
		}
	}
	sort.SliceStable(me.Edges, func(i, j int) bool {
		a, b := me.Edges[i], me.Edges[j]
		if a.From != b.From {
			return a.From < b.From
		}
		if a.To != b.To {
			return a.To < b.To
		}
		return a.Declaration < b.Declaration
	})
	me.fold(byNS)
	return me
}

// edgeState says what became of a declaration reached from elsewhere.
func (m *model) edgeState(d *decl, f *finding, state func(*finding) string) string {
	if f != nil {
		return state(f)
	}
	if d.scope == "shared" {
		switch d.source.kind {
		case srcOwn, srcBlock, srcType, srcFile:
			// Declared, if some config would leave it private without
			// the directive.
			if s, src := m.scopeOf(d, map[*directive]bool{d.source.dir: true}); s == "private" || src.kind == srcDefault {
				return "declared"
			}
		}
		return "open"
	}
	return "unchecked"
}

// fold groups the edges into crossings.
func (me *Measure) fold(byNS map[*namespace]*NamespaceInfo) {
	type pair struct{ from, to string }
	index := make(map[pair]*Crossing)
	declsIn := make(map[string]int)
	for _, info := range byNS {
		declsIn[info.Namespace] = info.Declarations
	}
	// Which namespaces reach each declaration through a finding.
	reachers := make(map[*decl]map[string]bool)
	for _, e := range me.Edges {
		if e.State == "open" {
			continue
		}
		if reachers[e.decl] == nil {
			reachers[e.decl] = make(map[string]bool)
		}
		reachers[e.decl][e.From] = true
		k := pair{e.From, e.To}
		c := index[k]
		if c == nil {
			c = &Crossing{From: e.From, To: e.To, Declarations: declsIn[e.To]}
			index[k] = c
			me.Crossings = append(me.Crossings, c)
		}
		c.Reached++
		c.Uses += e.Uses
		switch e.State {
		case "declared":
			c.Declared++
		case "baselined":
			c.Baselined++
		case "reported":
			c.Reported++
		case "ignored":
			c.Ignored++
		case "unchecked":
			c.Unchecked++
		}
	}
	for _, c := range me.Crossings {
		_, c.Mutual = index[pair{c.To, c.From}]
		pairNS := map[string]bool{c.From: true, c.To: true}
		seen := make(map[*decl]bool)
		for _, e := range me.Edges {
			if e.State != "reported" && e.State != "baselined" || seen[e.decl] {
				continue
			}
			if !pairNS[e.To] {
				continue
			}
			from := reachers[e.decl]
			ok := len(from) > 0
			for ns := range from {
				if !pairNS[ns] {
					ok = false
				}
			}
			if ok {
				seen[e.decl] = true
				c.Clears++
			}
		}
	}
	sort.SliceStable(me.Crossings, func(i, j int) bool {
		a, b := me.Crossings[i], me.Crossings[j]
		if a.Reached != b.Reached {
			return a.Reached > b.Reached
		}
		if a.Uses != b.Uses {
			return a.Uses > b.Uses
		}
		if a.From != b.From {
			return a.From < b.From
		}
		return a.To < b.To
	})
}

