func loadEmbedded() []*embeddedSkill {
	entries, err := fs.ReadDir(skillsFS, "skills")
	if err != nil {
		panic(err)
	}
	var skills []*embeddedSkill
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		sub, err := fs.Sub(skillsFS, path.Join("skills", e.Name()))
		if err != nil {
			panic(err)
		}
