package skill

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// agent is a coding agent whose skills directory the tool can write to.
type agent struct {
	name    string
	project string // skills directory, relative to the project root
	user    string // skills directory, relative to the home directory
}

// agents in the order the tool reports them.
var agents = []agent{
	{"github-copilot", ".agents/skills", ".copilot/skills"},
	{"claude-code", ".claude/skills", ".claude/skills"},
	{"cursor", ".agents/skills", ".cursor/skills"},
	{"codex", ".agents/skills", ".codex/skills"},
	{"gemini", ".agents/skills", ".gemini/skills"},
	{"antigravity", ".agents/skills", ".gemini/antigravity/skills"},
}

const (
	scopeProject = "project"
	scopeUser    = "user"
)

func lookupAgent(name string) (agent, bool) {
	for _, a := range agents {
		if a.name == name {
			return a, true
		}
	}
	return agent{}, false
}

// skillsDir returns where the agent keeps its skills in the given scope.
func (a agent) skillsDir(scope, root string) (string, error) {
	if scope == scopeProject {
		return filepath.Join(root, a.project), nil
	}
	if a.name == "claude-code" {
		if dir := strings.TrimSpace(os.Getenv("CLAUDE_CONFIG_DIR")); dir != "" {
			abs, err := filepath.Abs(dir)
			if err != nil {
				return "", err
			}
			return filepath.Join(abs, "skills"), nil
		}
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	home, err = filepath.Abs(home)
	if err != nil {
		return "", err
	}
	return filepath.Join(home, a.user), nil
}

// parseAgents splits the -agent values into names, checking each one.
func parseAgents(values []string) ([]string, error) {
	var names []string
	for _, v := range values {
		for _, name := range strings.Split(v, ",") {
			name = strings.TrimSpace(name)
			if name == "" {
				continue
			}
			if _, ok := lookupAgent(name); !ok && name != "all" && name != "detected" {
				known := make([]string, len(agents))
				for i, a := range agents {
					known[i] = a.name
				}
				sort.Strings(known)
				return nil, fmt.Errorf("skillembed: unknown agent %q (want one of %s, or all, or detected)",
					name, strings.Join(known, ", "))
			}
			names = append(names, name)
		}
	}
	return names, nil
}

// selectAgents expands all and detected. An agent is detected when the
// directory holding its skills directory exists; when detection is all that
// was asked for and it finds nothing, every agent is selected.
func selectAgents(names []string, scope, root string) ([]agent, error) {
	if len(names) == 0 {
		return nil, errors.New("skillembed: no agent selected")
	}
	var selected []agent
	seen := make(map[string]bool)
	add := func(a agent) {
		if !seen[a.name] {
			seen[a.name] = true
			selected = append(selected, a)
		}
	}
	for _, name := range names {
		switch name {
		case "all":
			for _, a := range agents {
				add(a)
			}
		case "detected":
			for _, a := range agents {
				dir, err := a.skillsDir(scope, root)
				if err != nil {
					return nil, err
				}
				if isDir(filepath.Dir(dir)) {
					add(a)
				}
			}
		default:
			a, _ := lookupAgent(name)
			add(a)
		}
	}
	if len(selected) == 0 {
		selected = append(selected, agents...)
	}
	return selected, nil
}

// targetDirs returns the distinct skills directories of the agents. In the
// project scope each must stay inside the project root once symbolic links
// are followed.
func targetDirs(selected []agent, scope, root string) ([]string, error) {
	var dirs []string
	seen := make(map[string]bool)
	for _, a := range selected {
		dir, err := a.skillsDir(scope, root)
		if err != nil {
			return nil, err
		}
		if !seen[dir] {
			seen[dir] = true
			dirs = append(dirs, dir)
		}
	}
	if scope == scopeProject {
		for _, dir := range dirs {
			if err := checkInside(root, dir); err != nil {
				return nil, err
			}
		}
	}
	return dirs, nil
}

// findProjectRoot walks up from the working directory to the nearest
// directory holding .git. Below that, the nearest directory already holding
// an agent's skills parent wins. Without a repository the working directory
// is the root. The home directory is refused, since the user scope is meant
// for it.
func findProjectRoot() (string, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", err
	}
	root, marked := cwd, ""
	for dir := cwd; ; dir = filepath.Dir(dir) {
		if marked == "" && (isDir(filepath.Join(dir, ".agents")) || isDir(filepath.Join(dir, ".claude"))) {
			marked = dir
		}
		if exists(filepath.Join(dir, ".git")) {
			root = dir
			if marked != "" {
				root = marked
			}
			break
		}
		if filepath.Dir(dir) == dir {
			break
		}
	}
	if home, err := os.UserHomeDir(); err == nil && sameDir(root, home) {
		return "", fmt.Errorf("skillembed: the search landed on the home directory (%s), "+
			"so pass --scope user to write there on purpose or --dir to name another directory", root)
	}
	return root, nil
}

func sameDir(a, b string) bool {
	ra, err := filepath.EvalSymlinks(a)
	if err != nil {
		return false
	}
	rb, err := filepath.EvalSymlinks(b)
	if err != nil {
		return false
	}
	return ra == rb
}

// checkInside fails when dir, with its symbolic links followed, lies outside
// root.
func checkInside(root, dir string) error {
	realRoot, err := filepath.EvalSymlinks(root)
	if err != nil {
		return err
	}
	realDir, err := resolve(dir)
	if err != nil {
		return err
	}
	if rel, err := filepath.Rel(realRoot, realDir); err != nil || rel == ".." || strings.HasPrefix(rel, "../") {
		return fmt.Errorf("skillembed: the destination is outside the project root (%s is really %s), "+
			"so pass --dir to write there on purpose", dir, realDir)
	}
	return nil
}

// resolve follows the symbolic links of an absolute path, including dangling
// ones, keeping whatever part of it does not exist yet.
func resolve(p string) (string, error) {
	return resolveLinks(p, 0)
}

func resolveLinks(p string, hops int) (string, error) {
	resolved, err := filepath.EvalSymlinks(p)
	if err == nil {
		return resolved, nil
	}
	if !errors.Is(err, fs.ErrNotExist) {
		return "", err
	}
	if fi, lerr := os.Lstat(p); lerr == nil && fi.Mode()&fs.ModeSymlink != 0 {
		if hops++; hops > 255 {
			return "", errors.New("EvalSymlinks: too many links")
		}
		link, err := os.Readlink(p)
		if err != nil {
			return "", err
		}
		if !filepath.IsAbs(link) {
			link = filepath.Join(filepath.Dir(p), link)
		}
		return resolveLinks(link, hops)
	}
	parent := filepath.Dir(p)
	if parent == p {
		return p, nil
	}
	resolvedParent, err := resolveLinks(parent, hops)
	if err != nil {
		return "", err
	}
	return filepath.Join(resolvedParent, filepath.Base(p)), nil
}

func isDir(p string) bool {
	fi, err := os.Stat(p)
	return err == nil && fi.IsDir()
}

func exists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}
package skill

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

// plan is what a subcommand works on: the skills directories it targets and
// the state of every skill in them, taken before anything is changed.
type plan struct {
	root   string // project root; "" when the targets were not found from one
	dirs   []string
	skills []*embeddedSkill // as named on the command line, repeats included
	items  []item
}

// item is one skill directory in a target.
type item struct {
	name  string
	dir   string // the skills directory holding it
	path  string
	state state
	skill *embeddedSkill // nil for an orphan
}

// makePlan checks the options and inspects the targets. The order of the
// steps decides which error is reported first: scope, project root, agent
// names, target directories, reading them, then skill names.
func makePlan(o options) (*plan, error) {
	if o.scope != scopeProject && o.scope != scopeUser {
		return nil, fmt.Errorf("skillembed: unknown scope %q (want project or user)", o.scope)
	}
	p := new(plan)
	if o.dir == "" && o.scope == scopeProject {
		root, err := findProjectRoot()
		if err != nil {
			return nil, err
		}
		p.root = root
	}
	names, err := parseAgents(o.agents)
	if err != nil {
		return nil, err
	}
	if o.dir != "" {
		dir, err := filepath.Abs(o.dir)
		if err != nil {
			return nil, err
		}
		p.dirs = []string{dir}
	} else {
		selected, err := selectAgents(names, o.scope, p.root)
		if err != nil {
			return nil, err
		}
		if p.dirs, err = targetDirs(selected, o.scope, p.root); err != nil {
			return nil, err
		}
	}

	entries := make([][]fs.DirEntry, len(p.dirs))
	for i, dir := range p.dirs {
		es, err := os.ReadDir(dir)
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		}
		entries[i] = es
	}

	if p.skills, err = selectSkills(o.skills); err != nil {
		return nil, err
	}
	for i, dir := range p.dirs {
		for _, s := range p.skills {
			path := filepath.Join(dir, s.name)
			st, err := inspect(path, s.digest)
			if err != nil {
				return nil, err
			}
			p.items = append(p.items, item{name: s.name, dir: dir, path: path, state: st, skill: s})
		}
		if len(o.skills) > 0 {
			continue // orphans are only looked for when every skill is in play
		}
		for _, e := range entries[i] {
			name := e.Name()
			if !e.IsDir() || strings.HasPrefix(name, ".") || lookupSkill(name) != nil {
				continue
			}
			path := filepath.Join(dir, name)
			st, err := inspect(path, "")
			if err != nil {
				return nil, err
			}
			// Installed by this tool and untouched since: with no embedded
			// skill to compare against, that reads as outdated.
			if st == stateOutdated {
				p.items = append(p.items, item{name: name, dir: dir, path: path, state: stateOrphaned})
			}
		}
	}
	return p, nil
}

// selectSkills returns the embedded skills named, or all of them.
func selectSkills(names []string) ([]*embeddedSkill, error) {
	if len(names) == 0 {
		return embedded, nil
	}
	var skills []*embeddedSkill
	for _, name := range names {
		s := lookupSkill(name)
		if s == nil {
			known := make([]string, len(embedded))
			for i, s := range embedded {
				known[i] = s.name
			}
			return nil, fmt.Errorf("skillembed: unknown skill %q (embedded: %s)", name, strings.Join(known, ", "))
		}
		skills = append(skills, s)
	}
	return skills, nil
}

func (c *cli) install(p *plan, o options) int {
	installedAt := time.Now().UTC().Format(time.RFC3339)
	var (
		results []result
		refused []item
		err     error
	)
	for _, it := range p.items {
		r := result{name: it.name, path: it.path}
		switch {
		case it.state == stateOrphaned:
			r.verb, r.note = "removed", "no longer embedded in "+toolName
			if !o.dryRun {
				if rerr := os.RemoveAll(it.path); rerr != nil {
					err = fmt.Errorf("remove %s from %s: %w", it.name, it.dir, rerr)
				}
			}
		case it.state == stateUpToDate && !o.force:
			r.verb, r.note = "skipped", "already up to date"
		case it.state == stateModified && !o.force:
			r.verb, r.note = "skipped", noteEdited
			refused = append(refused, it)
		case it.state == stateForeign && !o.force:
			r.verb, r.note = "skipped", noteForeign
			refused = append(refused, it)
		default:
			r.verb = "updated"
			if it.state == stateMissing {
				r.verb = "installed"
			}
			if !o.dryRun {
				if ierr := installSkill(it, installedAt); ierr != nil {
					err = fmt.Errorf("install %s into %s: %w", it.name, it.dir, ierr)
				}
			}
		}
		if err != nil {
			break
		}
		results = append(results, r)
	}
	c.report(p, o.dryRun, results)
	if err != nil {
		return c.fail(err)
	}
	if len(refused) > 0 {
		var b strings.Builder
		b.WriteString("refusing to overwrite skills this tool did not install, or that were edited after installing:\n")
		for _, it := range refused {
			fmt.Fprintf(&b, "  %s (%s)\n", it.path, it.state)
		}
		b.WriteString("re-run with --force to overwrite")
		return c.fail(errors.New(b.String()))
	}
	return 0
}

func (c *cli) uninstall(p *plan, o options) int {
	var (
		results []result
		err     error
	)
	for _, it := range p.items {
		r := result{name: it.name, path: it.path}
		switch {
		case it.state == stateMissing:
			r.verb, r.note = "skipped", "not installed"
		case it.state == stateModified && !o.force:
			r.verb, r.note = "skipped", noteEdited
		case it.state == stateForeign && !o.force:
			r.verb, r.note = "skipped", noteForeign
		default:
			r.verb = "removed"
			if !o.dryRun {
				err = os.RemoveAll(it.path)
			}
		}
		if err != nil {
			break
		}
		results = append(results, r)
	}
	c.report(p, o.dryRun, results)
	if err != nil {
		return c.fail(err)
	}
	return 0
}

// installSkill writes the skill into a temporary directory beside its
// destination, then swaps it into place, so a reader never sees half of it.
func installSkill(it item, installedAt string) error {
	if err := os.MkdirAll(it.dir, 0o755); err != nil {
		return err
	}
	tmp, err := os.MkdirTemp(it.dir, "."+it.name+".tmp-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmp) // gone already once renamed into place

	meta := [][2]string{
		{keyBy, toolName},
		{keyVersion, toolVersion},
		{keyAt, strconv.Quote(installedAt)},
		{keyDigest, strconv.Quote(it.skill.digest)},
	}
	if err := writeFiles(it.skill.files, tmp, meta); err != nil {
		return err
	}

	// Reserve a name to move the previous install aside to.
	old, err := os.MkdirTemp(it.dir, "."+it.name+".old-*")
	if err != nil {
		return err
	}
	if err := os.Remove(old); err != nil {
		return err
	}
	if err := os.Rename(it.path, old); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	if err := os.Rename(tmp, it.path); err != nil {
		os.Rename(old, it.path) // put the previous install back
		return err
	}
	os.RemoveAll(old) // best effort: the new install is in place
	return nil
}

// writeFiles copies a skill into dir, adding the install metadata to its
// SKILL.md.
func writeFiles(files fs.FS, dir string, meta [][2]string) error {
	return fs.WalkDir(files, ".", func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		target := filepath.Join(dir, filepath.FromSlash(p))
		if d.IsDir() {
			return os.MkdirAll(target, 0o755)
		}
		data, err := fs.ReadFile(files, p)
		if err != nil {
			return err
		}
		if p == skillFile {
			data = render(data, meta)
		}
		return os.WriteFile(target, data, 0o644)
	})
}
package skill

import (
	"errors"
	"io/fs"
	"os"
	"path/filepath"
)

// state is where a skill directory stands against the embedded skills.
type state int

const (
	stateMissing  state = iota // nothing there
	stateUpToDate              // installed by this tool, current, untouched
	stateOutdated              // installed by an older build of this tool, untouched
	stateModified              // installed by this tool, then edited
	stateForeign               // not installed by this tool
	stateOrphaned              // installed by this tool, which no longer carries it
)

func (s state) String() string {
	return [...]string{"missing", "up-to-date", "outdated", "modified", "foreign", "orphaned"}[s]
}

// inspect reports the state of the skill directory dir, given the digest of
// the embedded skill of that name ("" for none).
func inspect(dir, current string) (state, error) {
	fi, err := os.Stat(dir)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return stateMissing, nil
		}
		return 0, err
	}
	if !fi.IsDir() {
		return stateForeign, nil
	}
	data, err := os.ReadFile(filepath.Join(dir, skillFile))
	if err != nil {
		return stateForeign, nil
	}
	meta, ok := parseMeta(data)
	if !ok || meta[keyBy] != toolName || meta[keyDigest] == "" {
		return stateForeign, nil
	}
	actual, err := digestFS(os.DirFS(dir))
	if err != nil {
		return stateForeign, nil
	}
	switch recorded := meta[keyDigest]; {
	case actual != recorded:
		return stateModified, nil
	case recorded == current:
		return stateUpToDate, nil
	default:
		return stateOutdated, nil
	}
}
package skill

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io/fs"
)

// skillFile is the file every skill directory has at its root.
const skillFile = "SKILL.md"

// junkFiles are written by file managers, not by people, so a skill
// directory holding them is still the one that was installed.
var junkFiles = map[string]bool{".DS_Store": true, "Thumbs.db": true, "desktop.ini": true}

// digestFS hashes the regular files of a skill directory in walk order. Each
// file contributes its slash-separated path, its length and its content,
// with SKILL.md taken without its install metadata. Anything other than a
// directory or a regular file makes the directory one the digest cannot
// describe.
func digestFS(fsys fs.FS) (string, error) {
	h := sha256.New()
	err := fs.WalkDir(fsys, ".", func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() || junkFiles[d.Name()] {
			return nil
		}
		if !d.Type().IsRegular() {
			return fmt.Errorf("%s: not a regular file", p)
		}
		data, err := fs.ReadFile(fsys, p)
		if err != nil {
			return err
		}
		if p == skillFile {
			data = normalize(data)
		}
		fmt.Fprintf(h, "%s\x00%d\x00", p, len(data))
		h.Write(data)
		return nil
	})
	if err != nil {
		return "", err
	}
	return "sha256:" + hex.EncodeToString(h.Sum(nil)), nil
}

