	}
	st.reasons()
	st.findings(configPath)
}

// collect records the exported declarations of a judged package.
func (st *shrinkState) collect(su *shrinkUnit) {
	m := su.model
	info := su.pkg.TypesInfo
	add := func(id *ast.Ident, kind string, f *fileInfo, doc *ast.CommentGroup, t *target) *shrinkCand {
		if id == nil || !ast.IsExported(id.Name) {
			return nil
		}
		obj := info.Defs[id]
		if obj == nil {
			return nil
		}
		c := &shrinkCand{obj: obj, name: id.Name, kind: kind, ident: id, key: id.Name, file: f, doc: doc, target: t, unit: su, ns: f.ns.key(), isTest: f.isTest}
		su.cands = append(su.cands, c)
		st.byObj[st.symKey(obj)] = c
		return c
	}
	for _, f := range m.files {
		for _, t := range f.targets {
			switch t.kind {
			case tFunc:
				fd := t.node.(*ast.FuncDecl)
				if fd.Recv == nil {
					if f.isTest && isTestFunc(fd.Name.Name) {
						continue
					}
					add(fd.Name, "func", f, fd.Doc, t)
					continue
				}
				c := add(fd.Name, "method", f, fd.Doc, t)
				if c == nil {
					continue
				}
				c.method = true
				if fn, ok := c.obj.(*types.Func); ok && fn.Signature().Recv() != nil {
					if n := baseNamed(fn.Signature().Recv().Type()); n != nil {
						c.typeOf = n.Obj()
						c.key = n.Obj().Name() + "." + c.name
						st.members[st.symKey(c.typeOf)] = append(st.members[st.symKey(c.typeOf)], c)
					}
				}
			case tGen, tBlock:
				gd := t.node.(*ast.GenDecl)
				for i, s := range gd.Specs {
					stt := t
					if t.kind == tBlock {
						stt = t.children[i]
					}
					switch s := s.(type) {
					case *ast.ValueSpec:
						kind := "var"
						if gd.Tok == token.CONST {
							kind = "const"
						}
						doc := s.Doc
						if t.kind == tGen {
							doc = gd.Doc
						}
						for _, id := range s.Names {
							add(id, kind, f, doc, stt)
						}
					case *ast.TypeSpec:
						doc := s.Doc
						if t.kind == tGen {
							doc = gd.Doc
						}
						add(s.Name, "type", f, doc, stt)
						tn, _ := info.Defs[s.Name].(*types.TypeName)
						st.collectFields(su, f, s, stt, tn)
					}
				}
			}
		}
	}
}

func isTestFunc(name string) bool {
	for _, p := range []string{"Test", "Benchmark", "Fuzz", "Example"} {
		if strings.HasPrefix(name, p) {
			return true
		}
	}
	return false
}

func (st *shrinkState) collectFields(su *shrinkUnit, f *fileInfo, s *ast.TypeSpec, stt *target, tn *types.TypeName) {
	stype, ok := s.Type.(*ast.StructType)
	if !ok || tn == nil {
		return
	}
	info := su.pkg.TypesInfo
	i := 0
	for _, ft := range stt.children {
		if ft.kind != tField {
			continue
		}
		field := stype.Fields.List[i]
		i++
		for _, id := range field.Names {
			if !ast.IsExported(id.Name) {
				continue
			}
			obj := info.Defs[id]
			if obj == nil {
				continue
			}
			c := &shrinkCand{obj: obj, name: id.Name, kind: "field", ident: id, key: tn.Name() + "." + id.Name, file: f, doc: field.Doc, target: ft, unit: su, ns: f.ns.key(), member: true, typeOf: tn, isTest: f.isTest}
			su.cands = append(su.cands, c)
			st.byObj[st.symKey(obj)] = c
			st.members[st.symKey(tn)] = append(st.members[st.symKey(tn)], c)
		}
	}
}

// symKey names an object the same way in every load: package path, then
// the type for a method or a field, then the name.
func (st *shrinkState) symKey(obj types.Object) string {
	obj = origin(obj)
	pkg := obj.Pkg()
	if pkg == nil {
		return ""
	}
	switch o := obj.(type) {
	case *types.Func:
		if recv := o.Signature().Recv(); recv != nil {
			if n := baseNamed(recv.Type()); n != nil {
				return pkg.Path() + "." + n.Obj().Name() + "." + o.Name()
			}
			return ""
		}
	case *types.Var:
		if o.IsField() {
			owner := st.fieldOwner(o)
			if owner == "" {
				return ""
			}
			return pkg.Path() + "." + owner + "." + o.Name()
		}
	}
	if obj.Parent() != pkg.Scope() {
		return ""
	}
	return pkg.Path() + "." + obj.Name()
}

// fieldOwner names the package-level type whose struct declares a field.
func (st *shrinkState) fieldOwner(v *types.Var) string {
	m := st.owners[v.Pkg()]
	if m == nil {
		m = make(map[*types.Var]string)
		scope := v.Pkg().Scope()
		for _, name := range scope.Names() {
			tn, ok := scope.Lookup(name).(*types.TypeName)
			if !ok {
				continue
			}
			if s, ok := tn.Type().Underlying().(*types.Struct); ok {
				for i := 0; i < s.NumFields(); i++ {
					m[s.Field(i)] = name
				}
			}
		}
		st.owners[v.Pkg()] = m
	}
	return m[v]
}

// mark records a use of an object from package from.
func (st *shrinkState) mark(obj types.Object, from string) {
	c := st.byObj[st.symKey(obj)]
	if c == nil || from == c.unit.path {
		return
	}
	if from == c.unit.path+"_test" {
		c.xtest = true
		return
	}
	c.external = true
}

// scanUses records the uses one package makes of judged declarations.
func (st *shrinkState) scanUses(u *unit) {
	info := u.pkg.TypesInfo
	if info == nil {
		return
	}
	from := u.path
	for _, f := range u.pkg.Syntax {
		ast.Inspect(f, func(n ast.Node) bool {
			switch n := n.(type) {
			case *ast.Ident:
				if obj := info.Uses[n]; obj != nil {
					st.mark(obj, from)
					// An embedded field is spelled with its type's name.
					if v, ok := obj.(*types.Var); ok && v.Embedded() {
						if nt := baseNamed(v.Type()); nt != nil {
							st.mark(nt.Obj(), from)
						}
					}
				}
			case *ast.CompositeLit:
				if len(n.Elts) == 0 {
					break
				}
				if _, keyed := n.Elts[0].(*ast.KeyValueExpr); keyed {
					break
				}
				if s := literalStruct(info.TypeOf(n)); s != nil {
					for i := range n.Elts {
						if i < s.NumFields() {
							st.mark(s.Field(i), from)
						}
					}
				}
			}
			return true
		})
		conversions(info, f, func(t, iface types.Type, live bool) {
			if live {
				st.escape(t, map[types.Type]bool{})
			}
			st.satisfies(t, iface)
		})
	}
	// The types of the expressions of another package reach the types they
	// mention. The external tests' expressions do not: they reach a type
	// only by naming it.
	for _, tv := range info.Types {
		if tv.Type == nil {
			continue
		}
		walkNamed(tv.Type, map[types.Type]bool{}, func(tn *types.TypeName) {
			if c := st.byObj[st.symKey(tn)]; c != nil && from == c.unit.path+"_test" {
				return
			}
			st.mark(tn, from)
		})
	}
}

// walkNamed calls visit for every named type a type mentions, without
// looking inside the named types themselves.
func walkNamed(t types.Type, seen map[types.Type]bool, visit func(*types.TypeName)) {
	if t == nil || seen[t] {
		return
	}
	seen[t] = true
	switch t := t.(type) {
	case *types.Named:
		visit(t.Origin().Obj())
		for i := 0; i < t.TypeArgs().Len(); i++ {
			walkNamed(t.TypeArgs().At(i), seen, visit)
		}
	case *types.Alias:
		visit(t.Obj())
		walkNamed(types.Unalias(t), seen, visit)
	case *types.Pointer:
		walkNamed(t.Elem(), seen, visit)
	case *types.Slice:
		walkNamed(t.Elem(), seen, visit)
	case *types.Array:
		walkNamed(t.Elem(), seen, visit)
	case *types.Map:
		walkNamed(t.Key(), seen, visit)
		walkNamed(t.Elem(), seen, visit)
	case *types.Chan:
		walkNamed(t.Elem(), seen, visit)
	case *types.Signature:
		walkNamed(t.Params(), seen, visit)
		walkNamed(t.Results(), seen, visit)
	case *types.Tuple:
		for i := 0; i < t.Len(); i++ {
			walkNamed(t.At(i).Type(), seen, visit)
		}
	case *types.Struct:
		for i := 0; i < t.NumFields(); i++ {
			walkNamed(t.Field(i).Type(), seen, visit)
		}
	}
}

// escape marks a type whose values may be read through an interface or by
// reflection: the type, its methods and its fields, and the types of its
// fields in turn.
func (st *shrinkState) escape(t types.Type, seen map[types.Type]bool) {
	if t == nil || seen[t] {
		return
	}
	seen[t] = true
	switch t := t.(type) {
	case *types.Named:
		tn := t.Origin().Obj()
		if k := st.symKey(tn); !st.escaped[k] {
			st.escaped[k] = true
			if c := st.byObj[k]; c != nil {
				c.external = true
			}
			for _, c := range st.members[k] {
				c.external = true
			}
		}
		st.escape(t.Underlying(), seen)
	case *types.Alias:
		st.escape(types.Unalias(t), seen)
	case *types.Pointer:
		st.escape(t.Elem(), seen)
	case *types.Slice:
		st.escape(t.Elem(), seen)
	case *types.Array:
		st.escape(t.Elem(), seen)
	case *types.Map:
		st.escape(t.Key(), seen)
		st.escape(t.Elem(), seen)
	case *types.Chan:
		st.escape(t.Elem(), seen)
	case *types.Struct:
		for i := 0; i < t.NumFields(); i++ {
			if c := st.byObj[st.symKey(t.Field(i))]; c != nil {
				c.external = true
			}
			st.escape(t.Field(i).Type(), seen)
		}
	}
}

// satisfies marks the methods of t that an interface asks for.
func (st *shrinkState) satisfies(t, iface types.Type) {
	it, ok := iface.Underlying().(*types.Interface)
	if !ok || it.NumMethods() == 0 {
		return
	}
	ms := types.NewMethodSet(t)
	if _, isPtr := t.(*types.Pointer); !isPtr {
		ms = types.NewMethodSet(types.NewPointer(t))
	}
	for i := 0; i < it.NumMethods(); i++ {
		if sel := ms.Lookup(it.Method(i).Pkg(), it.Method(i).Name()); sel != nil {
			if c := st.byObj[st.symKey(sel.Obj())]; c != nil {
				c.external = true
			}
		}
	}
}

// tagged treats a struct with a tagged field as read by a marshaller.
func (st *shrinkState) tagged(su *shrinkUnit) {
	for _, c := range su.cands {
		tn, ok := c.obj.(*types.TypeName)
		if !ok {
			continue
		}
		s, ok := tn.Type().Underlying().(*types.Struct)
		if !ok {
			continue
		}
		for i := 0; i < s.NumFields(); i++ {
			if s.Tag(i) != "" {
				st.escape(tn.Type(), map[types.Type]bool{})
				break
			}
		}
	}
}

// scanExcluded reads the Go files of the module that no package loaded,
// for the names they write, since they are not type-checked.
func (st *shrinkState) scanExcluded(us []*unit) {
	loaded := make(map[string]bool)
	var roots []string
	for _, u := range us {
		p := u.pkg
		for _, f := range p.GoFiles {
			loaded[f] = true
		}
		for _, f := range p.CompiledGoFiles {
			loaded[f] = true
		}
		if p.Raw != nil {
			for _, list := range [][]string{p.TestGoFiles(), p.XTestGoFiles()} {
				for _, f := range list {
					loaded[f] = true
				}
			}
		}
		if p.Module != nil && p.Module.Dir != "" {
			roots = append(roots, p.Module.Dir)
		}
	}
	sort.Strings(roots)
	byDir := make(map[string]*shrinkUnit)
	for _, su := range st.res.units {
		byDir[su.pkg.Dir] = su
	}
	seenRoot := make(map[string]bool)
	for _, root := range roots {
		if seenRoot[root] {
			continue
		}
		seenRoot[root] = true
		for _, path := range moduleGoFiles(root) {
			if loaded[path] {
				continue
			}
			st.readExcluded(path, byDir)
		}
	}
}

		}
		if n := len(tv); n > 0 {
			seq = append(seq, tv[n-1])
			tv = tv[:n-1]
		}
		seq = append(append(seq, todo...), tv...)
		for _, f := range seq {
			ld.parseFile(f)
		}
	}
	var wg sync.WaitGroup

	// Type-check in dependency order, running independent packages in parallel.
	done := make(map[*Package]chan struct{}, len(order))
	for _, p := range order {
		done[p] = make(chan struct{})
	}
	for _, p := range order {
		wg.Add(1)
		go func(p *Package) {
			defer wg.Done()
			for _, imp := range p.Imports {
				<-done[imp]
			}
			ld.loadPackage(p)
			close(done[p])
		}(p)
	}
	wg.Wait()
}

func (ld *loader) parseFile(filename string) (*ast.File, error) {
	ld.parseMu.Lock()
	v, ok := ld.cache[filename]
	if ok {
		ld.parseMu.Unlock()
		<-v.ready
		return v.f, v.err
	}
	v = &parseValue{ready: make(chan struct{})}
	ld.cache[filename] = v
	ld.parseMu.Unlock()
	src, err := os.ReadFile(filename)
	if err != nil {
		v.err = err
	} else {
		v.f, v.err = parser.ParseFile(ld.fset, filename, src, parser.AllErrors|parser.ParseComments)
	}
	close(v.ready)
	return v.f, v.err
}

func (ld *loader) parseFiles(filenames []string) ([]*ast.File, []error) {
	var parsed []*ast.File
	var errs []error
	for _, filename := range filenames {
		f, err := ld.parseFile(filename)
		if f != nil {
			parsed = append(parsed, f)
		}
		if err != nil {
			errs = append(errs, err)
		}
	}
	return parsed, errs
}

func (ld *loader) loadFromExportData(lpkg *Package) error {
	ld.exportMu.Lock()
	defer ld.exportMu.Unlock()
	if lpkg.Types != nil && lpkg.Types.Complete() {
		return nil
	}
	lpkg.IllTyped = true
	if lpkg.ExportFile == "" {
		return fmt.Errorf("no export data file")
	}
	tpkg, err := ld.imp.ImportFrom(lpkg.PkgPath, "", 0)
	if err != nil {
		return fmt.Errorf("reading %s: %v", lpkg.ExportFile, err)
	}
	lpkg.Types = tpkg
	lpkg.IllTyped = false
	return nil
}

func (ld *loader) loadPackage(lpkg *Package) {
	if lpkg.loaded {
		return
	}
	lpkg.loaded = true
	if lpkg.PkgPath == "unsafe" {
		lpkg.Types = types.Unsafe
		lpkg.Syntax = []*ast.File{}
		lpkg.TypesInfo = new(types.Info)
		lpkg.TypesSizes = ld.sizes
		return
	}
	if !lpkg.needtypes && !lpkg.needsrc {
		lpkg.Types = types.NewPackage(lpkg.PkgPath, lpkg.Name)
		return
	}
	if !lpkg.needsrc {
		if err := ld.loadFromExportData(lpkg); err != nil {
			lpkg.Errors = append(lpkg.Errors, Error{Pos: "-", Msg: err.Error(), Kind: UnknownError})
		}
		return
	}
	lpkg.Types = types.NewPackage(lpkg.PkgPath, lpkg.Name)

	appendError := func(err error) {
		var errs []Error
		switch err := err.(type) {
		case Error:
			errs = append(errs, err)
		case *os.PathError:
			errs = append(errs, Error{Pos: err.Path + ":1", Msg: err.Err.Error(), Kind: ParseError})
		case scanner.ErrorList:
			for _, err := range err {
				errs = append(errs, Error{Pos: err.Pos.String(), Msg: err.Msg, Kind: ParseError})
			}
		case scanner.Error:
			errs = append(errs, Error{Pos: err.Pos.String(), Msg: err.Msg, Kind: ParseError})
		case types.Error:
			lpkg.TypeErrors = append(lpkg.TypeErrors, err)
			errs = append(errs, Error{Pos: err.Fset.Position(err.Pos).String(), Msg: err.Msg, Kind: TypeError})
		default:
			errs = append(errs, Error{Pos: "-", Msg: err.Error(), Kind: UnknownError})
		}
		lpkg.Errors = append(lpkg.Errors, errs...)
	}

	if len(lpkg.CompiledGoFiles) == 0 && lpkg.ExportFile != "" {
		appendError(Error{"-", fmt.Sprintf("sources missing for package %s", lpkg.ID), ParseError})
		_ = ld.loadFromExportData(lpkg)
		return
	}

	files, errs := ld.parseFiles(lpkg.CompiledGoFiles)
	for _, err := range errs {
		appendError(err)
	}
	lpkg.Syntax = files
	lpkg.TypesInfo = &types.Info{
		Types:        make(map[ast.Expr]types.TypeAndValue),
		Defs:         make(map[*ast.Ident]types.Object),
		Uses:         make(map[*ast.Ident]types.Object),
		Implicits:    make(map[ast.Node]types.Object),
		Instances:    make(map[*ast.Ident]types.Instance),
		Scopes:       make(map[ast.Node]*types.Scope),
		Selections:   make(map[*ast.SelectorExpr]*types.Selection),
		FileVersions: make(map[*ast.File]string),
	}
	lpkg.TypesSizes = ld.sizes

	imp := importerFunc(func(path string) (*types.Package, error) {
		if path == "unsafe" {
			return types.Unsafe, nil
		}
		ipkg := lpkg.Imports[path]
		if ipkg == nil {
			if err := lpkg.importErrors[path]; err != nil {
				return nil, err
			}
			return nil, fmt.Errorf("no metadata for %s", path)
		}
		if ipkg.Types != nil && ipkg.Types.Complete() {
			return ipkg.Types, nil
		}
		return nil, fmt.Errorf("internal error: package %q without types was imported from %q", path, lpkg)
	})

	tc := &types.Config{
		Importer:         imp,
		IgnoreFuncBodies: !ld.cfg.Deps && !lpkg.Initial,
		Error:            appendError,
		Sizes:            ld.sizes,
	}
	if lpkg.Module != nil && lpkg.Module.GoVersion != "" {
		tc.GoVersion = "go" + lpkg.Module.GoVersion
	}
	err := types.NewChecker(tc, ld.fset, lpkg.Types, lpkg.TypesInfo).Files(lpkg.Syntax)
	lpkg.importErrors = nil
	if err != nil && len(lpkg.Errors) == 0 {
		appendError(err)
	}
	illTyped := len(lpkg.Errors) > 0
	if !illTyped {
		for _, imp := range lpkg.Imports {
			if imp.IllTyped {
				illTyped = true
				break
			}
		}
	}
	lpkg.IllTyped = illTyped
}

type importerFunc func(path string) (*types.Package, error)

func (f importerFunc) Import(path string) (*types.Package, error) { return f(path) }

// Visit visits all the packages in the import graph rooted at pkgs, calling
// post for each in postorder (dependencies first, imports sorted by path).
func Visit(pkgs []*Package, pre func(*Package) bool, post func(*Package)) {
	seen := make(map[*Package]bool)
	var visit func(*Package)
	visit = func(pkg *Package) {
		if !seen[pkg] {
			seen[pkg] = true
			if pre == nil || pre(pkg) {
				paths := make([]string, 0, len(pkg.Imports))
				for path := range pkg.Imports {
					paths = append(paths, path)
				}
				sort.Strings(paths)
				for _, path := range paths {
					visit(pkg.Imports[path])
				}
			}
			if post != nil {
				post(pkg)
			}
		}
	}
	for _, pkg := range pkgs {
		visit(pkg)
	}
}

// PrintErrors prints the errors of every package in the import graph rooted
// at pkgs, dependencies first, and returns how many it printed.
func PrintErrors(w io.Writer, pkgs []*Package) int {
	var n int
	errModules := make(map[*Module]bool)
	Visit(pkgs, nil, func(pkg *Package) {
		for _, err := range pkg.Errors {
			fmt.Fprintln(w, err)
			n++
		}
		mod := pkg.Module
		if mod != nil && mod.Error != nil && !errModules[mod] {
			errModules[mod] = true
			fmt.Fprintln(w, mod.Error.Err)
			n++
		}
	})
	return n
}

// Recheck type-checks a source package again with every function body, and
// returns the errors it finds. It reports what a package that was only
// checked as a dependency would report had it been named itself.
func Recheck(p *Package) []Error {
	if len(p.Syntax) == 0 {
		return nil
	}
	var errs []Error
	imp := importerFunc(func(path string) (*types.Package, error) {
		if path == "unsafe" {
			return types.Unsafe, nil
		}
		ipkg := p.Imports[path]
		if ipkg == nil || ipkg.Types == nil || !ipkg.Types.Complete() {
			return nil, fmt.Errorf("no metadata for %s", path)
		}
		return ipkg.Types, nil
	})
	tc := &types.Config{
		Importer: imp,
		Sizes:    p.TypesSizes,
		Error: func(err error) {
			if te, ok := err.(types.Error); ok {
				errs = append(errs, Error{Pos: te.Fset.Position(te.Pos).String(), Msg: te.Msg, Kind: TypeError})
			}
		},
	}
	if p.Module != nil && p.Module.GoVersion != "" {
		tc.GoVersion = "go" + p.Module.GoVersion
	}
	pkg := types.NewPackage(p.PkgPath, p.Name)
	_ = types.NewChecker(tc, p.Fset, pkg, &types.Info{}).Files(p.Syntax)
	return errs
}
"}

