package analyzer

import (
	"path/filepath"
	"strings"
)

// Rules is the effective configuration for one package: every key resolved
// down the chain of config files.
type Rules struct {
	Unexported string // "shared" or "private"
	// UnexportedSet records whether a config file stated defaults.unexported.
	UnexportedSet bool
	Qualify       string // "always", "never" or "ondemand"
	Exported      bool
	Vocabulary    map[string][]string
	Boundary      bool
	Surplus       string // "off", "loose" or "strict"
	Unused        string // "off", "loose" or "strict"

	// Only holds one pattern list per stating file; a file must match every
	// list. Omit holds every omit pattern of the chain.
	Only []PatternList
	Omit []Pattern

	// Baseline is the path of the baseline to consult, or "".
	Baseline string
	// BaselineSet records whether a config file named the baseline.
	BaselineSet bool

	// Chain lists the config files read, outermost first.
	Chain []string
}

// PatternList is the filter.only list of one config file.
type PatternList struct {
	Dir      string
	Patterns []Pattern
}

// Pattern is a filter glob anchored at the directory of its config file.
type Pattern struct {
	Dir  string
	Text string
}

// DefaultRules returns the built-in defaults.
func DefaultRules() *Rules {
	return &Rules{
		Unexported: "private",
		Qualify:    "never",
		Boundary:   true,
		Surplus:    "strict",
		Unused:     "strict",
		Vocabulary: map[string][]string{},
	}
}

// FileSection is one parsed config file.
type FileSection struct {
	Path  string
	Shown string // the path as it was named
	Dir   string

	Unexported *string
	Qualify    *string
	Exported   *bool
	Vocabulary map[string][]string
	VocabOrder []string
	Boundary   *string
	Surplus    *string
	Unused     *string
	Only       []string
	OnlySet    bool
	Omit       []string
	Baseline   *string
}

// compose resolves a chain of config files, outermost first.
func compose(chain []*FileSection) *Rules {
	r := DefaultRules()
	for _, f := range chain {
		r.Chain = append(r.Chain, f.Shown)
		if f.Unexported != nil {
			r.Unexported = *f.Unexported
			r.UnexportedSet = true
		}
		if f.Qualify != nil {
			r.Qualify = *f.Qualify
		}
		if f.Exported != nil {
			r.Exported = *f.Exported
		}
		for ns, words := range f.Vocabulary {
			r.Vocabulary[ns] = words
		}
		if f.Boundary != nil {
			r.Boundary = *f.Boundary == "on"
		}
		if f.Surplus != nil {
			r.Surplus = *f.Surplus
		}
		if f.Unused != nil {
			r.Unused = *f.Unused
		}
		if len(f.Only) > 0 {
			list := PatternList{Dir: f.Dir}
			for _, p := range f.Only {
				list.Patterns = append(list.Patterns, Pattern{Dir: f.Dir, Text: p})
			}
			r.Only = append(r.Only, list)
		}
		for _, p := range f.Omit {
			r.Omit = append(r.Omit, Pattern{Dir: f.Dir, Text: p})
		}
		if f.Baseline != nil {
			r.Baseline = filepath.Join(f.Dir, *f.Baseline)
			r.BaselineSet = true
		}
	}
	return r
}

// match reports whether the file at path matches the pattern, which is read
// against the pattern's directory with .gitignore anchoring.
func (p Pattern) match(path string) bool {
	rel, err := filepath.Rel(p.Dir, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, "../") {
		return false
	}
	rel = filepath.ToSlash(rel)
	pat := p.Text
	dirOnly := strings.HasSuffix(pat, "/")
	pat = strings.TrimSuffix(pat, "/")
	anchored := false
	switch {
	case strings.HasPrefix(pat, "./"):
		pat = strings.TrimPrefix(pat, "./")
		anchored = true
	case strings.HasPrefix(pat, "/"):
		pat = strings.TrimPrefix(pat, "/")
		anchored = true
	case strings.Contains(pat, "/"):
		anchored = true
	}
	if dirOnly {
		pat += "/**"
	}
	if !anchored {
		pat = "**/" + pat
	}
	return globMatch(strings.Split(pat, "/"), strings.Split(rel, "/"))
}

// globMatch matches path segments against pattern segments. "**" matches
// any number of segments, though a trailing one needs at least one: a
// directory pattern names what is inside it.
func globMatch(pat, segs []string) bool {
	if len(pat) == 0 {
		return len(segs) == 0
	}
	if pat[0] == "**" {
		min := 0
		if len(pat) == 1 {
			min = 1
		}
		for i := min; i <= len(segs); i++ {
			if globMatch(pat[1:], segs[i:]) {
				return true
			}
		}
		return false
	}
	if len(segs) == 0 || !segMatch(pat[0], segs[0]) {
		return false
	}
	return globMatch(pat[1:], segs[1:])
}

// segMatch matches one path segment, where '*' matches any run of
// characters and '?' any one character.
func segMatch(pat, s string) bool {
	p, n := []rune(pat), []rune(s)
	var match func(i, j int) bool
	match = func(i, j int) bool {
		for i < len(p) {
			switch p[i] {
			case '*':
				for k := j; k <= len(n); k++ {
					if match(i+1, k) {
						return true
					}
				}
				return false
			case '?':
				if j >= len(n) {
					return false
				}
			default:
				if j >= len(n) || p[i] != n[j] {
					return false
				}
			}
			i++
			j++
		}
		return j == len(n)
	}
	return match(0, 0)
}

// admits reports whether the filter lets a file be read.
func (r *Rules) admits(path string) bool {
	for _, list := range r.Only {
		matched := false
		for _, p := range list.Patterns {
			if p.match(path) {
				matched = true
				break
			}
		}
		if !matched {
			return false
		}
	}
	for _, p := range r.Omit {
		if p.match(path) {
			return false
		}
	}
	return true
}
package analyzer

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"sync"

	"declscope/internal/load"
	"declscope/internal/yaml"
)

// sections describes the config file layout: the Go type name the decoder
// reports for each section, its dotted path, and the keys it takes.
var sections = map[string]struct {
	path string
	keys []string
}{
	"config.File":            {"", []string{"defaults", "rules", "filter", "baseline"}},
	"config.defaultsSection": {"defaults", []string{"unexported"}},
	"config.rulesSection":    {"rules", []string{"naming", "boundary", "surplus", "unused"}},
	"config.namingSection":   {"rules.naming", []string{"qualify", "exported", "vocabulary"}},
	"config.filterSection":   {"filter", []string{"only", "omit"}},
}

// decoder decodes config nodes with the conventions of yaml.v3.
type decoder struct {
	terrors []string
}

// failure aborts decoding with a plain error.
type failure struct{ err error }

func (d *decoder) terror(n *yaml.Node, tag, into string) {
	if n.Tag != "" {
		tag = n.Tag
	}
	short := shortTagOf(tag)
	value := n.Value
	if short != "!!seq" && short != "!!map" {
		if len(value) > 10 {
			value = " `" + value[:7] + "...`"
		} else {
			value = " `" + value + "`"
		}
	} else {
		value = ""
	}
	d.terrors = append(d.terrors, fmt.Sprintf("line %d: cannot unmarshal %s%s into %s", n.Line, short, value, into))
}

func shortTagOf(tag string) string {
	const long = "tag:yaml.org,2002:"
	if strings.HasPrefix(tag, long) {
		return "!!" + tag[len(long):]
	}
	return tag
}

// resolve follows aliases and documents to the node holding the value.
func resolveNode(n *yaml.Node) *yaml.Node {
	for n != nil {
		switch n.Kind {
		case yaml.DocumentNode:
			if len(n.Content) == 0 {
				return nil
			}
			n = n.Content[0]
		case yaml.AliasNode:
			n = n.Alias
		default:
			return n
		}
	}
	return nil
}

func isNull(n *yaml.Node) bool {
	return n == nil || n.Kind == yaml.ScalarNode && n.ShortTag() == "!!null"
}

// checkExplicit fails like yaml.v3 when an explicit tag does not match the
// value it tags.
func checkExplicit(n *yaml.Node) {
	if n.Kind != yaml.ScalarNode || n.Style&yaml.TaggedStyle == 0 {
		return
	}
	tag := n.ShortTag()
	switch tag {
	case "!!str", "!!null", "!!binary", "!!merge", "!!seq", "!!map":
		return
	}
	plain := &yaml.Node{Kind: yaml.ScalarNode, Value: n.Value}
	got := plain.ShortTag()
	if got == tag {
		return
	}
	if tag == "!!float" && got == "!!int" {
		return
	}
	if tag == "!!timestamp" && got == "!!str" {
		return
	}
	switch tag {
	case "!!int", "!!float", "!!bool", "!!timestamp":
		panic(failure{fmt.Errorf("yaml: cannot decode %s `%s` as a %s", got, n.Value, tag)})
	}
}

// str decodes a scalar into a string.
func (d *decoder) str(n *yaml.Node) (string, bool) {
	n = resolveNode(n)
	if isNull(n) {
		return "", false
	}
	switch n.Kind {
	case yaml.ScalarNode:
		checkExplicit(n)
		return n.Value, true
	case yaml.SequenceNode:
		d.terror(n, "!!seq", "string")
	case yaml.MappingNode:
		if d.dupKeys(n) {
			return "", false
		}
		d.terror(n, "!!map", "string")
	}
	return "", false
}

// boolean decodes a scalar into a bool with yaml.v3's YAML 1.1 leniency.
func (d *decoder) boolean(n *yaml.Node) (bool, bool) {
	n = resolveNode(n)
	if isNull(n) {
		return false, false
	}
	if n.Kind == yaml.ScalarNode {
		checkExplicit(n)
		quoted := n.Style&(yaml.SingleQuotedStyle|yaml.DoubleQuotedStyle|yaml.LiteralStyle|yaml.FoldedStyle) != 0 || n.ShortTag() == "!!str"
		if !quoted {
			switch n.Value {
			case "true", "True", "TRUE":
				return true, true
			case "false", "False", "FALSE":
				return false, true
			}
		}
		switch n.Value {
		case "y", "Y", "yes", "Yes", "YES", "on", "On", "ON":
			return true, true
		case "n", "N", "no", "No", "NO", "off", "Off", "OFF":
			return false, true
		}
	}
	panic(failure{errors.New("want true or false")})
}

// strings decodes a sequence of scalars.
func (d *decoder) stringList(n *yaml.Node) ([]string, bool) {
	n = resolveNode(n)
	if isNull(n) {
		return nil, false
	}
	switch n.Kind {
	case yaml.SequenceNode:
		out := []string{}
		for _, item := range n.Content {
			if s, ok := d.str(item); ok {
				out = append(out, s)
			} else if isNull(resolveNode(item)) {
				out = append(out, "")
			}
		}
		return out, true
	case yaml.MappingNode:
		if d.dupKeys(n) {
			return nil, false
		}
		d.terror(n, "!!map", "[]string")
	default:
		checkExplicit(n)
		d.terror(n, n.ShortTag(), "[]string")
	}
	return nil, false
}

// dupKeys reports duplicate keys of a mapping like yaml.v3 does.
func (d *decoder) dupKeys(n *yaml.Node) bool {
	before := len(d.terrors)
	l := len(n.Content)
	for i := 0; i < l; i += 2 {
		ni := n.Content[i]
		for j := i + 2; j < l; j += 2 {
			nj := n.Content[j]
			if ni.Kind == nj.Kind && ni.Value == nj.Value {
				d.terrors = append(d.terrors, fmt.Sprintf("line %d: mapping key %s already defined at line %d", nj.Line, strconv.Quote(nj.Value), ni.Line))
			}
		}
	}
	return len(d.terrors) > before
}

// mapping walks the key/value pairs of a mapping decoded into a struct type,
// including merged ones, calling field for every key.
func (d *decoder) structFields(n *yaml.Node, typeName string, field func(key string, keyNode, value *yaml.Node) bool) bool {
	n = resolveNode(n)
	if isNull(n) {
		return false
	}
	switch n.Kind {
	case yaml.MappingNode:
	case yaml.SequenceNode:
		d.terror(n, "!!seq", typeName)
		return false
	default:
		checkExplicit(n)
		d.terror(n, n.ShortTag(), typeName)
		return false
	}
	if d.dupKeys(n) {
		return false
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		k, v := n.Content[i], n.Content[i+1]
		if k.Kind == yaml.ScalarNode && k.ShortTag() == "!!merge" {
			d.merge(v, typeName, field)
			continue
		}
		key, ok := d.str(k)
		if !ok && !isNull(resolveNode(k)) {
			continue
		}
		if !field(key, k, v) {
			d.terrors = append(d.terrors, fmt.Sprintf("line %d: field %s not found in type %s", k.Line, key, typeName))
		}
	}
	return true
}

func (d *decoder) merge(v *yaml.Node, typeName string, field func(string, *yaml.Node, *yaml.Node) bool) {
	v = resolveNode(v)
	switch {
	case v != nil && v.Kind == yaml.MappingNode:
		d.structFields(v, typeName, field)
	case v != nil && v.Kind == yaml.SequenceNode:
		for i := len(v.Content) - 1; i >= 0; i-- {
			item := resolveNode(v.Content[i])
			if item == nil || item.Kind != yaml.MappingNode {
				panic(failure{errors.New("yaml: map merge requires map or sequence of maps as the value")})
			}
			d.structFields(item, typeName, field)
		}
	default:
		panic(failure{errors.New("yaml: map merge requires map or sequence of maps as the value")})
	}
}

