package yaml

import (
	"errors"
	"fmt"
)

// Parse parses the first document of data into a node tree, as
// yaml.Unmarshal(data, &node) does with gopkg.in/yaml.v3. It returns the
// document node, or nil if data holds no document (it is empty or holds only
// comments). On malformed input it returns the error yaml.v3 returns, such
// as "yaml: line 2: found character that cannot start any token".
//
// Anything after the first document is ignored, except that the scanner
// reads a few tokens ahead and reports an error it finds there.
func Parse(data []byte) (doc *Node, err error) {
	defer handleErr(&err)
	if len(data) == 0 {
		data = []byte{'\n'}
	}
	c := &composer{p: newParser(data), anchors: make(map[string]*Node)}
	c.expect(streamStartEvent)
	return c.parse(), nil
}

// syntaxError carries a parse error up to Parse.
type syntaxError struct{ err error }

func failf(format string, args ...any) {
	panic(syntaxError{fmt.Errorf("yaml: "+format, args...)})
}

func handleErr(err *error) {
	if v := recover(); v != nil {
		e, ok := v.(syntaxError)
		if !ok {
			panic(v)
		}
		*err = e.err
	}
}

// composer builds nodes from parser events, following yaml.v3.
type composer struct {
	p       *parser
	event   event // The event peeked at but not consumed yet, if any.
	anchors map[string]*Node
}

func (c *composer) fail() {
	panic(syntaxError{errors.New(c.p.errorMessage())})
}

// peek returns the type of the next event without consuming it.
func (c *composer) peek() eventType {
	if c.event.typ != noEvent {
		return c.event.typ
	}
	if !c.p.parse(&c.event) || c.p.err != noError {
		c.fail()
	}
	return c.event.typ
}

// expect consumes the next event, which must be of type t.
func (c *composer) expect(t eventType) {
	if c.event.typ == noEvent && !c.p.parse(&c.event) {
		c.fail()
	}
	if c.event.typ == streamEndEvent {
		failf("attempted to go past the end of stream; corrupted value?")
	}
	if c.event.typ != t {
		c.p.problem = fmt.Sprintf("expected %s event but got %s", t, c.event.typ)
		c.fail()
	}
	c.event = event{}
}

func (c *composer) parse() *Node {
	switch c.peek() {
	case scalarEvent:
		return c.scalar()
	case aliasEvent:
		return c.alias()
	case mappingStartEvent:
		return c.mapping()
	case sequenceStartEvent:
		return c.sequence()
	case documentStartEvent:
		return c.document()
	case streamEndEvent:
		return nil
	}
	panic("yaml: internal error: unexpected " + c.event.typ.String() + " event")
}

// node creates a node for the current event. An explicit tag other than
// the non-specific "!" wins; otherwise collections and quoted scalars get
// defaultTag and plain scalars a tag resolved from their value.
func (c *composer) node(kind Kind, defaultTag, tag, value string) *Node {
	var style Style
	switch {
	case tag != "" && tag != "!":
		tag = shortTag(tag)
		style = TaggedStyle
	case defaultTag != "":
		tag = defaultTag
	case kind == ScalarNode:
		tag = resolveTag(value)
	}
	return &Node{
		Kind:   kind,
		Style:  style,
		Tag:    tag,
		Value:  value,
		Line:   c.event.start.line + 1,
		Column: c.event.start.column + 1,
	}
}

func (c *composer) anchor(n *Node, anchor []byte) {
	if anchor != nil {
		n.Anchor = string(anchor)
		c.anchors[n.Anchor] = n
	}
}

func (c *composer) document() *Node {
	n := c.node(DocumentNode, "", "", "")
	c.expect(documentStartEvent)
	n.Content = append(n.Content, c.parse())
	c.peek()
	c.expect(documentEndEvent)
	return n
}

func (c *composer) alias() *Node {
	n := c.node(AliasNode, "", "", string(c.event.anchor))
	n.Alias = c.anchors[n.Value]
	if n.Alias == nil {
		failf("unknown anchor '%s' referenced", n.Value)
	}
	c.expect(aliasEvent)
	return n
}

func (c *composer) scalar() *Node {
	var style Style
	switch c.event.style {
	case doubleQuotedScalarStyle:
		style = DoubleQuotedStyle
	case singleQuotedScalarStyle:
		style = SingleQuotedStyle
	case literalScalarStyle:
		style = LiteralStyle
	case foldedScalarStyle:
		style = FoldedStyle
	}
	value := string(c.event.value)
	var defaultTag string
	if style != 0 {
		defaultTag = strTag
	} else if value == "<<" {
		defaultTag = mergeTag
	}
	n := c.node(ScalarNode, defaultTag, string(c.event.tag), value)
	n.Style |= style
	c.anchor(n, c.event.anchor)
	c.expect(scalarEvent)
	return n
}

func (c *composer) sequence() *Node {
	n := c.node(SequenceNode, seqTag, string(c.event.tag), "")
	if c.event.flow {
		n.Style |= FlowStyle
	}
	c.anchor(n, c.event.anchor)
	c.expect(sequenceStartEvent)
	for c.peek() != sequenceEndEvent {
		n.Content = append(n.Content, c.parse())
	}
	c.expect(sequenceEndEvent)
	return n
}

func (c *composer) mapping() *Node {
	n := c.node(MappingNode, mapTag, string(c.event.tag), "")
	if c.event.flow {
		n.Style |= FlowStyle
	}
	c.anchor(n, c.event.anchor)
	c.expect(mappingStartEvent)
	for c.peek() != mappingEndEvent {
		k := c.parse()
		v := c.parse()
		n.Content = append(n.Content, k, v)
	}
	c.expect(mappingEndEvent)
	return n
}
package analyzer

import (
	"path/filepath"
	"strings"
	"unicode"
	"unicode/utf8"
)

// initialisms are the words Go spells in one case throughout.
var initialisms = map[string]bool{
	"ACL": true, "API": true, "ASCII": true, "CPU": true, "CSS": true, "DNS": true,
	"EOF": true, "GUID": true, "HTML": true, "HTTP": true, "HTTPS": true, "ID": true,
	"IP": true, "JSON": true, "LHS": true, "QPS": true, "RAM": true, "RHS": true,
	"RPC": true, "SLA": true, "SMTP": true, "SQL": true, "SSH": true, "TCP": true,
	"TLS": true, "TTL": true, "UDP": true, "UI": true, "UID": true, "UUID": true,
	"URI": true, "URL": true, "UTF8": true, "VM": true, "XML": true, "XMPP": true,
	"XSRF": true, "XSS": true,
}

func isInitialism(s string) bool { return initialisms[strings.ToUpper(s)] }

// upperWord spells the leading word of s as it starts a word inside a
// camelCase name: "id" becomes "ID", "ids" "IDs", "user" "User".
func upperWord(s string) string {
	if s == "" {
		return s
	}
	if isInitialism(s) {
		return strings.ToUpper(s)
	}
	if strings.HasSuffix(s, "s") && len(s) > 1 && isInitialism(s[:len(s)-1]) {
		return strings.ToUpper(s[:len(s)-1]) + "s"
	}
	// The leading run of lower-case letters is the first word.
	n := 0
	for n < len(s) {
		r, size := utf8.DecodeRuneInString(s[n:])
		if !unicode.IsLower(r) {
			break
		}
		n += size
	}
	if n == 0 {
		return s
	}
	run, rest := s[:n], s[n:]
	if isInitialism(run) {
		return strings.ToUpper(run) + rest
	}
	if strings.HasSuffix(run, "s") && len(run) > 1 && isInitialism(run[:len(run)-1]) {
		return strings.ToUpper(run[:len(run)-1]) + "s" + rest
	}
	r, size := utf8.DecodeRuneInString(run)
	return string(unicode.ToUpper(r)) + run[size:] + rest
}

// lowerWord lowers the leading word of s the way Go unexports a name:
// "HTTPServer" becomes "httpServer", "URLs" "urls", "IPv4" "ipv4".
func lowerWord(s string) string {
	if s == "" {
		return s
	}
	if isInitialism(s) {
		return strings.ToLower(s)
	}
	if strings.HasSuffix(s, "s") && len(s) > 1 && isInitialism(s[:len(s)-1]) {
		return strings.ToLower(s)
	}
	// The leading run of upper-case letters.
	var runes []rune
	n := 0
	for n < len(s) {
		r, size := utf8.DecodeRuneInString(s[n:])
		if !unicode.IsUpper(r) {
			break
		}
		runes = append(runes, r)
		n += size
	}
	if n == 0 {
		return s
	}
	if n == len(s) {
		return strings.ToLower(s)
	}
	next, _ := utf8.DecodeRuneInString(s[n:])
	if !unicode.IsLower(next) || len(runes) == 1 {
		return strings.ToLower(s[:n]) + s[n:]
	}
	run := string(runes)
	lastSize := utf8.RuneLen(runes[len(runes)-1])
	head := run[:len(run)-lastSize]
	if !isInitialism(head) && isInitialism(run) {
		return strings.ToLower(run) + s[n:]
	}
	return strings.ToLower(head) + s[n-lastSize:]
}

// fileNamespace derives a namespace from a Go file name.
func fileNamespace(filename string) string {
	stem := strings.TrimSuffix(filename, ".go")
	if strings.HasSuffix(filename, "_test.go") {
		stem = strings.TrimSuffix(stem, "_test")
	}
	head, tail, hasDot := strings.Cut(stem, ".")
	head = stripOSArch(head)
	if hasDot {
		stem = head + "." + tail
	} else {
		stem = head
	}
	var segs []string
	start := -1
	for i, r := range stem {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			if start < 0 {
				start = i
			}
			continue
		}
		if start >= 0 {
			segs = append(segs, stem[start:i])
			start = -1
		}
	}
	if start >= 0 {
		segs = append(segs, stem[start:])
	}
	var b strings.Builder
	for i, seg := range segs {
		if i == 0 {
			b.WriteString(lowerWord(seg))
		} else {
			b.WriteString(upperWord(seg))
		}
	}
	return b.String()
}

// stripOSArch removes a GOOS or GOARCH suffix that go/build reads as a
// build constraint.
func stripOSArch(name string) string {
	i := strings.Index(name, "_")
	if i < 0 {
		return name
	}
	l := strings.Split(name[i:], "_")
	if n := len(l); n > 0 && l[n-1] == "test" {
		// A "_test" suffix here is part of the name, not a test marker,
		// but go/build skips it when looking for constraints.
		l = l[:n-1]
		n := len(l)
		if n >= 2 && knownOS[l[n-2]] && knownArch[l[n-1]] {
			return name
		}
		if n >= 1 && (knownOS[l[n-1]] || knownArch[l[n-1]]) {
			return name
		}
		return name
	}
	n := len(l)
	if n >= 2 && knownOS[l[n-2]] && knownArch[l[n-1]] {
		suffix := "_" + l[n-2] + "_" + l[n-1]
		return strings.TrimSuffix(name, suffix)
	}
	if n >= 1 && (knownOS[l[n-1]] || knownArch[l[n-1]]) {
		return strings.TrimSuffix(name, "_"+l[n-1])
	}
	return name
}

